src/infrastructure/stores/session.ts.source:
import { ref, computed } from 'vue';
import { defineStore } from 'pinia';
import {
    getAccount as apiGetAccount,
    refreshToken as apiRefreshToken,
    logout as apiLogout,
    logoutAll as apiLogoutAll,
    updateAccount as apiUpdateAccount
} from '@api';
import { getTokenFromResponse, getPayloadFromResponse } from '@/infrastructure/http/envelope.ts';

/**
 * The visitor's session: a token, and the least the app must know about whoever holds it.
 *
 * Deliberately a minimal projection — `{ id, email, admin }` — rather than the domain `User`,
 * which lives in `src/modules/account`. See `docs/theory/layers.md` for the split and for which
 * `/account` calls belong here.
 */

/** The least the app shell and the guards need to know about the signed-in visitor. */
export interface SessionViewer {
    id: string;
    email: string;
    admin: boolean;
}

/**
 * Writes a cookie through the prototype setter rather than `document.cookie`.
 *
 * Going through the original descriptor keeps the write working even when a library (or a test
 * double) has shadowed `document.cookie` on the instance.
 *
 * @param value - Full cookie string, attributes included.
 */
const setCookie = (value: string) => {
    const cookieDescriptor = Object.getOwnPropertyDescriptor(Document.prototype, 'cookie');
    cookieDescriptor?.set?.call(document, value);
};

export const useSessionStore = defineStore('session', () => {
    /**
     * User access token. In memory only — the refresh token is an httpOnly cookie the browser
     * never exposes, which is what makes a stolen bundle useless.
     */
    const accessToken = ref<string>();

    /** The signed-in visitor, as much of them as the shell and the guards are entitled to. */
    const viewer = ref<SessionViewer>();

    /**
     * Both derive from token AND viewer, not either alone: a token with no viewer is a session
     * that has been restored but not yet identified, and treating it as authenticated lets a
     * guard admit someone whose role is still unknown.
     */
    const isAuth = computed(() => Boolean(accessToken.value && viewer.value));
    const isAdmin = computed(() => Boolean(accessToken.value && viewer.value?.admin));

    /**
     * Records a freshly issued token and flags the JS-readable `isAuth` cookie.
     *
     * The cookie is not the credential — it is the hint that lets `tryRestoreAuth` skip a
     * pointless refresh round-trip for a visitor who was never signed in.
     *
     * @param token - Access token from a login or refresh response.
     */
    const setAccessToken = (token?: string) => {
        accessToken.value = token;
        if (token) setCookie('isAuth=true; path=/; SameSite=Lax');
    };

    /**
     * Records who the token belongs to.
     *
     * @param nextViewer - The claims projection, or `undefined` to forget it.
     */
    const setViewer = (nextViewer?: SessionViewer) => {
        viewer.value = nextViewer;
    };

    /**
     * Renews the in-memory access token using the httpOnly refresh cookie.
     *
     * @returns A promise resolving once the new token is stored.
     */
    const refreshToken = () =>
        apiRefreshToken().then((data) => {
            setAccessToken(getTokenFromResponse(data));
        });

    /**
     * Asks the API who the current token belongs to and stores the projection.
     *
     * @returns A promise resolving once `viewer` reflects the response.
     */
    const loadViewer = () =>
        apiGetAccount().then((data) => {
            // Typed structurally rather than as the generated `User`: naming the domain entity
            // here would put a `User` back into `infrastructure`.
            const payload = getPayloadFromResponse<{
                id: string;
                email: string;
                admin?: boolean;
            }>(data);
            setViewer(
                payload && { id: payload.id, email: payload.email, admin: Boolean(payload.admin) }
            );
            return payload;
        });

    /**
     * Remembers a signed-in visitor's language choice on their account.
     *
     * A guest's choice lives in the URL (`/:locale/...`) and dies with the tab, which is the right
     * lifetime for someone with no record to write to; a signed-in visitor's account record is the
     * one place a preference outlives the tab.
     *
     * The `isAuth` check is here rather than at the call site because it is a rule about the
     * preference, not about the button — a caller that forgot it would send an anonymous
     * `PUT /account` and get a 401. It is also what keeps `AppLanguageSwitcher` out of this store.
     *
     * Best-effort: callers fire it without awaiting, and a failed write is invisible, leaving the
     * stored preference stale until the next switch. A toast about a preference nobody asked to be
     * told about is the worse trade.
     *
     * @param locale - Language tag the visitor just chose.
     * @returns Resolves once the write settles, or immediately for a guest. Never rejects.
     */
    const persistLocalePreference = (locale: string): Promise<void> =>
        isAuth.value
            ? apiUpdateAccount({ locale })
                  .then(() => undefined)
                  .catch(() => undefined)
            : Promise.resolve();

    /**
     * Drops every trace of the session held here: token, viewer and the `isAuth` cookie.
     *
     * Domain caches are NOT cleared from here — the account module resets its own on logout.
     *
     * @returns Nothing; state is cleared as a side effect.
     */
    const clearSession = () => {
        accessToken.value = undefined;
        viewer.value = undefined;
        // The httpOnly jwt cookie can only be cleared server-side; isAuth is JS-accessible.
        setCookie('isAuth=; path=/; max-age=0; SameSite=Lax');
    };

    /**
     * Ends THIS session only: the refresh cookie's token is revoked server-side and local state is
     * cleared. Other devices keep their own tokens — `logoutAll` is the one that ends everything.
     *
     * @returns A promise resolving once the API call succeeds and local state is cleared.
     */
    const logout = () => apiLogout().then(() => clearSession());

    /**
     * Ends every session for this visitor, server-side and locally.
     *
     * @returns A promise resolving once the API call succeeds and local state is cleared.
     */
    const logoutAll = () => apiLogoutAll().then(() => clearSession());

    return {
        accessToken,
        viewer,
        isAuth,
        isAdmin,
        setAccessToken,
        setViewer,
        refreshToken,
        loadViewer,
        persistLocalePreference,
        clearSession,
        logout,
        logoutAll
    };
});

src/modules/cart/module.ts.source:
import { watch } from 'vue';
import { storeToRefs } from 'pinia';
import type { AppModule } from '@/kernel/registry';
import routes from './routes';
import { cartResponseSchemas } from './response-schemas';
import { useCartStore } from './store';
import { useSessionStore } from '@/infrastructure/stores/session.ts';

/**
 * The shopping cart, and the checkout that turns it into an order.
 *
 * Nearly every arrow points AT this module: orders reaches the cart barrel for the reorder button,
 * products for "add to cart", wishlist for its move-to-cart exit. The first two are
 * `customer-supplier` — they ask this store to write a line — and `wishlist` is `conformist`: the
 * move itself is a wishlist endpoint, and this store is only asked to refetch. Either way the cart
 * is the one publishing a store, while the modules it depends on publish components and schemas.
 *
 * The one arrow going out is `delivery`, and it is `published-language`: the checkout mounts
 * `ShippingSelector` and never learns what a shipping rate is.
 */
export default {
    name: 'cart',
    /*
     * Checkout is the one screen where price, stock, address and shipping have to agree at once,
     * and the only place this client holds a multi-step flow of its own. Every other module points
     * at it.
     */
    subdomain: 'core',
    dependsOn: [
        {
            module: 'delivery',
            as: 'published-language',
            because:
                'Mounts `ShippingSelector`, a self-contained component that renders shipping without this module learning what a rate is.'
        }
    ],
    routes,
    navigation: [
        {
            name: 'Cart',
            label: 'navigation.label-cart',
            plural: 1,
            order: 80,
            /*
             * The Badge of the glossary above, finally worn. Runs inside the shell's setup, so
             * stores are reachable; seeds from the lightweight `GET /cart/summary` whenever a
             * session appears, because the whole point of that endpoint is a count that does not
             * cost the cart. Every later mutation keeps the count fresh through the store.
             */
            badge: () => {
                const cartStore = useCartStore();
                const { isAuth } = storeToRefs(useSessionStore());
                watch(
                    isAuth,
                    (auth) => {
                        if (auth) void cartStore.fetchSummary();
                    },
                    { immediate: true }
                );
                return storeToRefs(cartStore).badgeQuantity;
            }
        }
    ],
    responseSchemas: cartResponseSchemas,
    locales: {
        en: () => import('./locales/en.json').then(({ default: dictionary }) => dictionary),
        it: () => import('./locales/it.json').then(({ default: dictionary }) => dictionary)
    }
} satisfies AppModule;

src/modules/demo/provided.ts.source:
import { ref, provide, inject } from 'vue';
import type { InjectionKey, Ref } from 'vue';

/**
 * The provide/inject demo, owned by the module that shows it off.
 *
 * It belongs here rather than in the composition root because the composition root is the file
 * every derived project edits first, and it has no business holding state that exactly one view
 * of one deletable module reads. Here, `rm -rf src/modules/demo` takes the feature with it, which
 * is the promise `src/modules.ts` makes about every module.
 */

/** What travels down the tree. A string, because the demo is about the mechanism. */
export type ProvidedVariable = string;

/** Paired mutation, so a descendant never writes to the injected ref directly. */
export type ProvidedVariableMutation = (value?: ProvidedVariable) => void;

/** The pair, as descendants receive it. */
export interface ProvidedVariableContext {
    providedVariable: Ref<ProvidedVariable>;
    setProvidedVariable: ProvidedVariableMutation;
}

/**
 * A typed key rather than the string `'providedVariable'`. A magic string has to be spelled the
 * same way in two files and nothing checks that it was; an `InjectionKey` carries the value's type
 * with it, so `inject` needs no annotation and a rename is a compile error on both sides.
 */
export const providedVariableKey: InjectionKey<ProvidedVariableContext> =
    Symbol('demo:providedVariable');

/**
 * Provides the pair to every descendant of the calling component.
 *
 * @returns The same pair, for the providing component's own use.
 */
export const provideVariable = (): ProvidedVariableContext => {
    const providedVariable = ref<ProvidedVariable>('From the Playground');

    const setProvidedVariable: ProvidedVariableMutation = (value = '') => {
        providedVariable.value = value;
    };

    const context = { providedVariable, setProvidedVariable };
    provide(providedVariableKey, context);
    return context;
};

/**
 * Injects the pair.
 *
 * Throws rather than falling back to a placeholder: a silent default renders a page that looks
 * like it works while demonstrating nothing, which is the one outcome a demo must not have.
 *
 * @returns The provided pair.
 */
export const useProvidedVariable = (): ProvidedVariableContext => {
    const context = inject(providedVariableKey);
    if (!context)
        throw new Error(
            'useProvidedVariable() needs an ancestor calling provideVariable() — see src/modules/demo/provided.ts.'
        );
    return context;
};

src/modules/locales/schemas.ts.source:
import { z } from 'zod';
import { translate } from '@/infrastructure/i18n';
import { LocaleScope } from '@types';

/**
 * Validation schemas for the locale admin's two forms.
 *
 * Messages are thunks resolved at parse time — see {@link translate} for why. It matters more here
 * than anywhere else in the app: this is the screen where a visitor changes the language, and
 * error text built as a plain string would stay in the old one while the labels around it moved.
 */

/**
 * A language tag as the contract accepts it: primary subtag, optional region.
 *
 * `pt-BR`, not `pt-br` and not `por`. The region's case carries meaning in BCP 47, and the API
 * stores the tag as given.
 */
const LANGUAGE_TAG_PATTERN = /^[a-z]{2}(-[A-Z]{2})?$/;

/**
 * Validation schema of the language form.
 *
 * `tag` is validated here for the CREATE case. Editing shows it disabled — it is what every entry
 * references, so the API keeps it immutable — and the dialog swaps this schema for
 * {@link localesLanguageEditSchema} rather than making the field conditionally optional, which
 * would leave a required field silently unchecked on the form that does write it.
 */
export const localesLanguageSchema = z.object({
    tag: z
        .string()
        .min(1, { error: () => translate('locale-form.tag-required') })
        .regex(LANGUAGE_TAG_PATTERN, { error: () => translate('locale-form.tag-invalid') }),
    name: z.string().min(1, { error: () => translate('locale-form.name-required') }),
    nativeName: z.string().min(1, { error: () => translate('locale-form.native-name-required') }),
    direction: z.enum(['ltr', 'rtl']),
    active: z.boolean()
});

/** The same form on edit, where the tag is shown but not writable. */
export const localesLanguageEditSchema = localesLanguageSchema.extend({
    tag: z.string()
});

/**
 * Validation schema of the entry form — adding only. A stored entry's key is immutable and its
 * value edits inline in the table, so a row never comes back through the dialog.
 */
export const localesEntrySchema = z.object({
    scope: z.enum(LocaleScope),
    key: z.string().min(1, { error: () => translate('entry-form.key-required') }),
    value: z.string().min(1, { error: () => translate('entry-form.value-required') })
});

