import type { AppModule } from '@/kernel/registry';
import routes from './routes';
import { wishlistResponseSchemas } from './response-schemas';

/**
 * The visitor's saved products.
 *
 * The one edge is the move-to-cart exit: the move is a WISHLIST endpoint, and the cart store is
 * then asked to refetch itself so the header's badge cannot lag a write this module initiated.
 * The reverse arrow does not exist — the cart never reads the wishlist — which is what keeps
 * `products → wishlist → cart → orders` a line rather than a loop.
 */
export default {
    name: 'wishlist',
    /*
     * A saved list with one exit into the cart. Deleting it costs a convenience, not a capability.
     */
    subdomain: 'supporting',
    routes,
    dependsOn: [
        {
            module: 'cart',
            as: 'conformist',
            because:
                'Move-to-cart calls a wishlist endpoint and then asks the cart store to refetch itself; the cart is never asked to write.'
        }
    ],
    navigation: [{ name: 'Wishlist', label: 'navigation.label-wishlist', plural: 1, order: 75 }],
    responseSchemas: wishlistResponseSchemas,
    locales: {
        en: () => import('./locales/en.json').then(({ default: dictionary }) => dictionary),
        it: () => import('./locales/it.json').then(({ default: dictionary }) => dictionary)
    }
} satisfies AppModule;

src/app/guards/authentications.ts.source:
import { storeToRefs } from 'pinia';
import { useSessionStore } from '@/infrastructure/stores/session';
import { useNotificationsStore } from '@guebbit/vue-toolkit';
import { getCookie } from '@guebbit/js-toolkit';
import { loginContinueTo } from '@/app/router/navigation';
import { translate } from '@/infrastructure/i18n';
import type { RouteLocationNormalized, RouteMeta } from 'vue-router';

/**
 * What a visitor must be to enter a route. Absent means public.
 *
 * - `guest` — anonymous only (login, signup, password reset): an authenticated visitor has no
 *   business on them and is sent home.
 * - `auth` — any authenticated visitor.
 * - `admin` — authenticated *and* admin.
 */
export type RouteAccess = 'guest' | 'auth' | 'admin';

/**
 * Declared on the route record, so `meta.access` is checked at compile time and a typo
 * (`acces: 'admin'`) is an error rather than a silently public page.
 */
declare module 'vue-router' {
    // The name belongs to the library being augmented, not to this codebase: declaration
    // merging only works against the exact interface it declares.
    interface RouteMeta {
        access?: RouteAccess;
    }
}

/**
 * Whether a visitor of the given standing may enter a route with the given requirement.
 *
 * The single expression of the access rule, so navigation and rendering cannot disagree: the
 * router calls it through {@link enforceRouteAccess} to decide whether to *allow* a page, and
 * `AppNavigation` calls it directly to decide whether to *show* the link to it. When those were
 * two separate lists, changing one silently produced either a visible link that bounced you or a
 * reachable page with no way to find it.
 *
 * @param access - The route's requirement, from `meta.access`. Absent means public.
 * @param visitor - The visitor's current standing, as the profile store reports it.
 * @returns `true` when the route may be entered and its link shown.
 */
export const canAccess = (
    access: RouteMeta['access'],
    visitor: { isAuth: boolean; isAdmin: boolean }
): boolean => {
    if (!access) return true;
    if (access === 'guest') return !visitor.isAuth;
    if (access === 'auth') return visitor.isAuth;
    return visitor.isAuth && visitor.isAdmin;
};

/**
 * Silently restores the in-memory access token via the refresh endpoint.
 *
 * Only attempted when the `isAuth` cookie is present — avoids a pointless
 * network round-trip for every guest page view. The cookie is written by
 * `setAccessToken`, which is the only thing that stores a token, so its presence
 * means a session existed on this browser at some point.
 *
 * @returns A promise that always resolves: already-authenticated and guest
 *  cases resolve immediately, and a failed refresh is swallowed.
 */
const restoreTokenIfNeeded = () => {
    const store = useSessionStore();
    if (store.accessToken || !getCookie('isAuth')) return Promise.resolve();
    return store.refreshToken().catch(() => undefined);
};

/**
 * Silently restores the session — token, then who it belongs to — without redirecting.
 *
 * Safe to use as a global guard or on public routes that show different content
 * depending on whether the visitor is an authenticated user or admin.
 *
 * @returns A promise resolving to `void` (a "proceed" verdict for the router)
 *  once the restore attempt has settled, successfully or not.
 */
export const tryRestoreAuth = (): Promise<void> => {
    const store = useSessionStore();
    return (
        restoreTokenIfNeeded()
            .then(() => {
                // The token alone is not a session: `isAuth`/`isAdmin` stay false until the
                // viewer is known, so a guard can never admit someone whose role it has not read.
                if (store.accessToken) return store.loadViewer();
            })
            // Discard the payload so the guard resolves to void (NavigationGuardReturn)
            .then(() => undefined)
            .catch(() => undefined)
    );
};

/**
 * Enforce a route's `meta.access`, notifying the visitor about any redirect.
 *
 * Mounted once globally rather than as a per-route `beforeEnter`, which is what makes
 * `meta.access` the only place a route's requirement is written down. It runs after
 * {@link tryRestoreAuth} in the same `beforeEach`, so the profile is already loaded and this
 * reads state instead of fetching it.
 *
 * @param to - Route being entered; supplies the requirement, the login `continue` target and the
 *  locale any redirect keeps.
 * @returns `undefined` to let the navigation through, or the location to redirect to. A blocked
 *  visitor is always told why — silently bouncing someone reads as a broken link.
 */
export const enforceRouteAccess = (to: RouteLocationNormalized) => {
    const { isAuth, isAdmin } = storeToRefs(useSessionStore());
    const visitor = { isAuth: isAuth.value, isAdmin: isAdmin.value };
    if (canAccess(to.meta.access, visitor)) return;

    const locale = to.params.locale as string;
    const { addMessage } = useNotificationsStore();

    // An authenticated visitor on a guests-only page: already where they wanted to be.
    if (to.meta.access === 'guest') {
        addMessage(translate('navigation.error-already-logged'));
        return { name: 'Home', params: { locale } };
    }

    // Anonymous: recoverable by logging in, so keep where they were going.
    if (!visitor.isAuth) {
        addMessage(translate('navigation.error-not-logged'));
        return loginContinueTo(to.fullPath, locale);
    }

    // Authenticated but not admin: logging in again cannot help, so no `continue` target.
    addMessage(translate('navigation.error-forbidden'));
    return { name: 'Home', params: { locale } };
};

src/infrastructure/composables/use-uploa.source:
import { useUploadProgress as useToolkitUploadProgress } from '@guebbit/vue-toolkit';
import type { AxiosProgressEvent, AxiosRequestConfig } from 'axios';

/**
 * Progress state for one form's image upload, and the wrapper that drives it.
 *
 * The state machine is the toolkit's — bar appears with the request, returns to idle however it
 * ends, nothing tracked when there is no file. All this adds is the axios binding, which lives
 * here once instead of in each of the five forms that upload.
 *
 * @returns `uploadProgress`, `undefined` while idle and 0–100 during a request, and
 *  {@link trackUpload} to wrap the call itself.
 */
export const useUploadProgress = () => {
    const { progress, track } = useToolkitUploadProgress<AxiosRequestConfig>((onProgress) => ({
        // `event.progress` is a 0–1 fraction, absent when the total size is unknown (a chunked or
        // compressed request) — reporting 0 keeps the bar still rather than jumping about.
        onUploadProgress: (event: AxiosProgressEvent) => onProgress(event.progress ?? 0)
    }));

    /**
     * Runs an API call with upload progress attached, and returns to idle however it ends.
     *
     * @param file - The picked file, or `undefined`. When absent nothing is tracked at all: on a
     *  plain field edit the bar would otherwise flash to 100% for a payload measured in bytes.
     * @param send - Performs the call. Receives the axios overrides to forward to the store
     *  method's `options` parameter, which is `undefined` when there is no file.
     * @returns Whatever `send` resolves with, untouched.
     */
    const trackUpload = <T>(
        file: File | undefined,
        send: (options?: AxiosRequestConfig) => Promise<T>
    ) => track(send, { enabled: !!file });

    return { uploadProgress: progress, trackUpload };
};

src/infrastructure/composables/use-app-f.source:
import { useI18n } from 'vue-i18n';
import { useNotificationsStore, useStructureFormValidation } from '@guebbit/vue-toolkit';
import { VUETIFY_INVALID_FIELD_SELECTOR } from '@/infrastructure/utils/errors.ts';
import type { MaybeRefOrGetter } from 'vue';
import type { ZodType } from 'zod';

/**
 * This application's three answers to `useStructureFormValidation`'s open questions.
 *
 * The toolkit is deliberately ignorant of vue-i18n, of Vuetify and of where a message goes — its
 * own docblock says so, and that is what makes it reusable. The consequence is that a correct form
 * here has to supply the same three things every time, and thirteen forms proved that does not
 * happen: five of them shipped missing at least one, and two of those had `showFormErrors` in
 * scope and declared a `ref(false)` beside it instead.
 *
 * So the policy is bound once, here, and a form supplies only what is genuinely its own: the
 * shape, the schema, and the element to focus into. Same relationship `formatCurrency` has with
 * the toolkit's `formatCurrencyBase` — the mechanism stays out there, the app's answers live in
 * one place.
 *
 * `tests/cross-cutting/form-idiom.spec.ts` is what keeps the fourteenth form from drifting.
 */
export interface UseAppFormSettings {
    /**
     * The `<form>` element, so a failed submit can focus the first invalid field.
     *
     * Omit it and `revealErrors()` degrades to a pure state change, which is the right shape for
     * a dialog: it already traps focus, so moving focus again inside it is a different question
     * from moving it on a page.
     */
    formElement?: MaybeRefOrGetter<HTMLElement | undefined | null>;
}

/**
 * A form, wired the way every form in this app is wired.
 *
 * @typeParam T - The form's field shape.
 * @param initialData - Starting values; also what `resetForm()` restores.
 * @param schema - Zod schema whose messages are thunks, so they resolve in the active language.
 * @param settings - See {@link UseAppFormSettings}.
 * @returns Everything `useStructureFormValidation` returns. `showFormErrors` is the gate a
 *  template reads — there is never a reason to declare another one beside it.
 */
/*
 * `any` rather than `unknown` because it mirrors the toolkit's own constraint, and because
 * `unknown` is the narrower of the two here: an interface has no index signature, so every form
 * shape in this app fails `Record<string, unknown>` and satisfies `Record<string, any>`.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- see above
export const useAppForm = <T extends Record<string, any>>(
    initialData: T,
    schema?: MaybeRefOrGetter<ZodType<T> | undefined>,
    { formElement }: UseAppFormSettings = {}
) => {
    const { t, locale } = useI18n();
    const { addMessage } = useNotificationsStore();

    return useStructureFormValidation<T>(initialData, schema, {
        // Re-parses the data so errors already on screen change language with the page. Without
        // it `formErrors` holds resolved strings, and a re-render just re-prints the old ones.
        revalidateOn: locale,
        formElement,
        invalidFieldSelector: VUETIFY_INVALID_FIELD_SELECTOR,
        onInvalid: () => addMessage(t('generic.fix-errors'))
    });
};

src/infrastructure/create-sse-client.ts.source:
import type { SseEventName, SseEventPayload } from '@types';

/** Callbacks registered on an SSE connection. */
export interface SseClientCallbacks {
    /** Called when the connection is successfully established. */
    onOpen?: () => void;
    /** Called when the browser fires an error event on the EventSource. */
    onError?: (error: Event) => void;
    /**
     * Called for each typed server-sent event.
     * The generic parameter `TEventName` narrows `payload` to the correct contract type.
     */
    onEvent?: <TEventName extends SseEventName>(
        eventName: TEventName,
        payload: SseEventPayload<TEventName>
    ) => void;
}

/** Handle returned by {@link createSseClient} to allow callers to close the connection. */
export interface SseClient {
    close: () => void;
}

/**
 * Safely parses a raw JSON string.
 *
 * @param rawData - Raw `data` field of an SSE frame.
 * @returns The parsed value, or `undefined` when the string is not valid JSON so
 *  callers can skip bad frames.
 */
const parseJsonData = (rawData: string) => {
    // eslint-disable-next-line no-restricted-syntax -- JSON.parse has no non-throwing form; a malformed SSE frame is dropped, not a crash
    try {
        return JSON.parse(rawData) as unknown;
    } catch {
        return;
    }
};

/**
 * Opens a persistent SSE connection and registers one listener per event name,
 * JSON-parsing each frame before forwarding it.
 *
 * @param url - SSE endpoint; opened with credentials so the auth cookie travels
 *  with it.
 * @param eventNames - Typed event names to subscribe to; one listener is
 *  registered per name so the browser dispatches them individually.
 * @param callbacks - Open/error/event handlers. Frames that fail to parse are
 *  dropped without invoking `onEvent`.
 * @returns An {@link SseClient} handle whose `close` method tears down the
 *  connection.
 */
export const createSseClient = (
    url: string,
    eventNames: readonly SseEventName[],
    callbacks: SseClientCallbacks = {}
): SseClient => {
    const eventSource = new EventSource(url, { withCredentials: true });

    eventSource.addEventListener('open', () => callbacks.onOpen?.());
    eventSource.addEventListener('error', (event) => callbacks.onError?.(event));

    // Register a listener per event name so the browser dispatches them individually
    for (const eventName of eventNames) {
        eventSource.addEventListener(eventName, (event) => {
            const payload = parseJsonData((event as MessageEvent<string>).data);
            // `undefined` is `parseJsonData`'s failure signal; `null`, `0`, `false` and `""` are
            // legitimate payloads.
            if (payload === undefined) return;

            callbacks.onEvent?.(eventName, payload as SseEventPayload<typeof eventName>);
        });
    }

    return {
        /** Closes the underlying EventSource and stops all SSE traffic. */
        close: () => eventSource.close()
    };
};

src/infrastructure/http/client.ts.source:
import axiosClient from 'axios';

/**
 * The shared axios instance every generated client goes through.
 *
 * Deliberately imports nothing of this app: it is the leaf of the http tier, so importing it can
 * never re-enter `index.ts` mid-evaluation.
 *
 * `withCredentials` is what carries the httpOnly refresh cookie, so the refresh flow works
 * without the token ever being readable from JS.
 */
export const instance = axiosClient.create({
    headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json; charset=utf-8'
    },
    withCredentials: true,
    timeout: Number.parseInt(import.meta.env.VITE_AXIOS_TIMEOUT ?? '10000')
});

// Prefix of every relative call; an absolute URL ignores it. `__E2E_API_URL` is the e2e shard
// runner's runtime override — each shard owns its own demo backend, and one built bundle cannot
// bake four URLs — set on the window before the app boots (see tests/support/e2e/commands.ts'
// `visit` overwrite). Nothing else ever defines it.
instance.defaults.baseURL =
    (globalThis as { __E2E_API_URL?: string }).__E2E_API_URL ?? import.meta.env.VITE_API_URL ?? '';

src/infrastructure/http/envelope.ts.source:
/**
 * Readers for the `{ data }` envelope the API wraps most payloads in.
 *
 * Here rather than in a store because the envelope is a property of the transport: a login
 * response and a product list arrive in the same wrapper, and neither is the session's business.
 */

/**
 * Narrows any value to a plain keyed object.
 *
 * @param value - Value to test.
 * @returns `true` when `value` is a non-null object.
 */
const isObjectRecord = (value: unknown): value is Record<string, unknown> =>
    typeof value === 'object' && value !== null;

/**
 * Detects the `{ data }` envelope.
 *
 * @param response - Raw API response.
 * @returns `true` when the value carries a `data` property.
 */
// eslint-disable-next-line @typescript-eslint/no-unnecessary-type-parameters -- the type parameter names the caller's payload in the predicate; without it the narrowing is to `unknown`
const isWrappedResponse = <T>(response: unknown): response is { data?: T } =>
    isObjectRecord(response) && 'data' in response;

/**
 * Reads the access token out of a login or refresh response, wrapped or not.
 *
 * @param response - Raw API response.
 * @returns The token, or `undefined` when the response carries none.
 */
export const getTokenFromResponse = (response?: unknown): string | undefined => {
    // Top level first: login answers with a bare `{ token }`, refresh wraps it in an envelope.
    if (isObjectRecord(response)) {
        const maybeToken = response.token;
        if (typeof maybeToken === 'string') return maybeToken;
    }
    if (isWrappedResponse<{ token?: string }>(response)) return response.data?.token;
    return undefined;
};

/**
 * Extracts the payload from both wrapped (`{ data }`) and direct responses.
 *
 * @typeParam T - Expected payload type.
 * @param response - Raw API response.
 * @returns The unwrapped payload, or `undefined` when absent.
 */
export const getPayloadFromResponse = <T>(response?: { data?: T } | T): T | undefined =>
    isWrappedResponse<T>(response) ? response.data : response;

