/**
 * Unit tests for the SSE composable behind the observability dashboard.
 *
 * `createSseClient` is mocked rather than driven through a real `EventSource`: what this file owns
 * is the wiring — which url is opened, which store action each event name reaches, and that the
 * module-level singleton is torn down before a second connection replaces it. The transport itself
 * is `tests/unit/infrastructure/create-sse-client.spec.ts`.
 *
 * Every case re-imports the module through `vi.resetModules()`, because `activeClient` lives at
 * module scope: without a fresh module a test would inherit the previous test's open connection and
 * the reconnect assertions would pass for the wrong reason.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import type { SseClientCallbacks } from '@/infrastructure/create-sse-client';
import type { MetricsSnapshotEvent, SseEventName } from '@types';

const close = vi.fn();

/**
 * The parameters are declared even though the body ignores them: `vi.fn(() => …)` types its
 * `mock.calls` as an empty tuple, so every assertion on what the composable PASSED — the url, the
 * event names, the callbacks — would be a type error rather than a check.
 */
const createSseClient = vi.fn(
    (_url?: string, _eventNames?: readonly SseEventName[], _callbacks?: SseClientCallbacks) => ({
        close
    })
);

vi.mock('@/infrastructure/create-sse-client', () => ({
    createSseClient: (...parameters: unknown[]) =>
        createSseClient(...(parameters as Parameters<typeof createSseClient>))
}));

/** Minimal payload accepted by every metrics event on the stream. */
const makeEvent = (timestamp: string): MetricsSnapshotEvent => ({
    timestamp,
    uptimeSeconds: 60,
    memory: { rss: 1, heapUsed: 1, heapTotal: 2, external: 0 },
    http: { totalRequests: 10, totalErrors: 0 },
    realtime: { sseClients: 1 }
});

/**
 * Imports the composable and its store fresh, so the module-level `activeClient` starts undefined.
 *
 * @returns The composable factory and the store hook from the same module graph.
 */
const loadComposable = async () => {
    vi.resetModules();
    const [{ useRealtimeObservability }, { useRealtimeObservabilityStore }] = await Promise.all([
        import('@/modules/realtime/use-realtime-observability'),
        import('@/modules/realtime/store')
    ]);
    return { useRealtimeObservability, useRealtimeObservabilityStore };
};

/** The callbacks handed to the last `createSseClient` call. */
const lastCallbacks = () => createSseClient.mock.calls.at(-1)![2]!;

describe('useRealtimeObservability', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    afterEach(() => {
        vi.unstubAllEnvs();
    });

    describe('connect', () => {
        it('opens the endpoint from VITE_API_SSE, for every contract event name', async () => {
            vi.stubEnv('VITE_API_SSE', 'https://api.example.com/observability/events');
            const { useRealtimeObservability } = await loadComposable();

            useRealtimeObservability().connect();

            expect(createSseClient).toHaveBeenCalledWith(
                'https://api.example.com/observability/events',
                [
                    'observability.heartbeat',
                    'observability.metrics.snapshot',
                    'observability.metrics.updated'
                ],
                expect.anything()
            );
        });

        it('falls back to the local dev endpoint when VITE_API_SSE is unset', async () => {
            vi.stubEnv('VITE_API_SSE', undefined);
            const { useRealtimeObservability } = await loadComposable();

            useRealtimeObservability().connect();

            expect(createSseClient.mock.calls[0]?.[0]).toBe(
                'http://localhost:3000/observability/events'
            );
        });

        it('reports connecting before the transport answers', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();

            expect(store.status).toBe('connecting');
        });

        it('closes the previous client so a second connect cannot leave two streams open', async () => {
            const { useRealtimeObservability } = await loadComposable();
            const { connect } = useRealtimeObservability();

            connect();
            expect(close).not.toHaveBeenCalled();

            connect();
            expect(close).toHaveBeenCalledTimes(1);
            expect(createSseClient).toHaveBeenCalledTimes(2);
        });
    });

    describe('transport callbacks', () => {
        it('reports open once the stream is established', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            lastCallbacks().onOpen?.();

            expect(store.status).toBe('open');
        });

        it('records both the error status and a message the dashboard can show', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            lastCallbacks().onError?.(new Event('error'));

            expect(store.status).toBe('error');
            expect(store.lastError).toBe('SSE connection error');
        });
    });

    describe('event routing', () => {
        it('sends a snapshot to setSnapshot and appends one snapshot entry', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:00:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.metrics.snapshot', payload);

            expect(store.latestSnapshot).toEqual(payload);
            // The early return is what keeps a snapshot out of the heartbeat branch below it
            expect(store.latestHeartbeatAt).toBeUndefined();
            expect(store.latestUpdate).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'snapshot-2026-01-01T00:00:00.000Z',
                    kind: 'snapshot',
                    timestamp: '2026-01-01T00:00:00.000Z',
                    payload
                }
            ]);
        });

        it('sends an update to setUpdate and appends one update entry', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:01:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.metrics.updated', payload);

            expect(store.latestUpdate).toEqual(payload);
            expect(store.latestSnapshot).toBeUndefined();
            expect(store.latestHeartbeatAt).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'update-2026-01-01T00:01:00.000Z',
                    kind: 'update',
                    timestamp: '2026-01-01T00:01:00.000Z',
                    payload
                }
            ]);
        });

        it('treats anything else as a heartbeat', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:02:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.heartbeat', payload);

            expect(store.latestHeartbeatAt).toBe('2026-01-01T00:02:00.000Z');
            expect(store.latestSnapshot).toBeUndefined();
            expect(store.latestUpdate).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'heartbeat-2026-01-01T00:02:00.000Z',
                    kind: 'heartbeat',
                    timestamp: '2026-01-01T00:02:00.000Z',
                    payload
                }
            ]);
        });

        it('keeps the feed in arrival order across event kinds', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            const callbacks = lastCallbacks();
            callbacks.onEvent?.(
                'observability.metrics.snapshot',
                makeEvent('2026-01-01T00:00:00.000Z')
            );
            callbacks.onEvent?.('observability.heartbeat', makeEvent('2026-01-01T00:00:30.000Z'));
            callbacks.onEvent?.(
                'observability.metrics.updated',
                makeEvent('2026-01-01T00:01:00.000Z')
            );

            expect(store.entries.map((entry) => entry.kind)).toEqual([
                'snapshot',
                'heartbeat',
                'update'
            ]);
        });
    });

    describe('disconnect', () => {
        it('closes the stream and reports closed', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const { connect, disconnect } = useRealtimeObservability();

            connect();
            disconnect();

            expect(close).toHaveBeenCalledTimes(1);
            expect(store.status).toBe('closed');
        });

        it('is safe with no connection open, and does not close a stream twice', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const { connect, disconnect } = useRealtimeObservability();

            disconnect();
            expect(close).not.toHaveBeenCalled();
            expect(store.status).toBe('closed');

            connect();
            disconnect();
            disconnect();
            expect(close).toHaveBeenCalledTimes(1);
        });

        it('reconnects after a disconnect without closing the released client again', async () => {
            const { useRealtimeObservability } = await loadComposable();
            const { connect, disconnect } = useRealtimeObservability();

            connect();
            disconnect();
            connect();

            expect(close).toHaveBeenCalledTimes(1);
            expect(createSseClient).toHaveBeenCalledTimes(2);
        });
    });

    it('exposes the store state alongside the controls', async () => {
        const { useRealtimeObservability, useRealtimeObservabilityStore } = await loadComposable();
        const store = useRealtimeObservabilityStore();
        const { status, latestSnapshot, latestUpdate, latestHeartbeatAt, entries, lastError } =
            useRealtimeObservability();

        store.setStatus('open');
        store.setError('nope');

        expect(status.value).toBe('open');
        expect(lastError.value).toBe('nope');
        expect(latestSnapshot.value).toBeUndefined();
        expect(latestUpdate.value).toBeUndefined();
        expect(latestHeartbeatAt.value).toBeUndefined();
        expect(entries.value).toEqual([]);
    });
});

tests/unit/infrastructure/http/http-refr.source:
/**
 * The 401 → refresh → replay flow, driven through the real interceptor chain.
 *
 * This is the one piece of client logic where a bug is both invisible to types and invisible to
 * the e2e suite: a broken refresh does not throw, it just logs the user out at some later moment.
 *
 * It is therefore tested against a real HTTP server (MSW's node interceptor) rather than a stubbed
 * axios adapter. The whole point is that `instance.interceptors.response` runs, that the *replay*
 * goes back through the same instance, and that `_dontRetry` actually stops the second round —
 * none of which a hand-rolled adapter would reproduce.
 *
 * `tests/unit/infrastructure/http/http.spec.ts` covers the error-normalisation side of the same
 * module with plain unit stubs; the two are complementary.
 *
 * ── How a case is written ────────────────────────────────────────────────────────────────────
 * The handlers below answer from {@link scenario}, and a case sets the one field it cares about.
 * Everything a case does NOT set is at its default, so what a test changes is exactly what it is
 * about. Assertions read {@link requestLog} — the server's own record of what arrived — because a
 * refresh attempt is not observable from the caller's side without stubbing the code under test.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';

/** Base URL the axios instance is built against; also what the handlers below are mounted on. */
const API = 'http://api.test';

/** The token a successful refresh hands back, and therefore what the replay must carry. */
const FRESH_TOKEN = 'fresh-token';

/**
 * Endpoints that must never trigger a refresh, mirroring `refreshExcludedPaths` in
 * `src/infrastructure/http/refresh.ts`.
 *
 * A 401 from any of them is a normal business outcome — wrong password, expired reset link, a
 * session already invalidated — so refreshing there turns a clean error message into an extra
 * round trip and, when the refresh also fails, a misleading session-expired state.
 */
const EXCLUDED_PATHS = [
    '/account/login',
    '/account/signup',
    '/account/reset',
    '/account/reset-confirm',
    '/account/logout-all'
];

/**
 * The same exclusion spelled absolutely.
 *
 * Generated clients send relative urls, but a caller passing an absolute one must get identical
 * treatment or the exclusion silently stops applying to it.
 */
const ABSOLUTE_EXCLUDED_URL = 'https://api.example.com/account/login';

/** One request as the server saw it. */
interface LoggedRequest {
    /** `METHOD /pathname`, which is what the assertions compare against. */
    route: string;
    /** The `Authorization` header, so the replay can be shown to carry the NEW token. */
    authorization?: string;
}

/** How the server should behave for one test. Reset to these defaults before every case. */
interface Scenario {
    /** How many more times `/account/refresh` may succeed; beyond that it answers 401. */
    refreshBudget: number;
    /** Answer the refresh with `200` and an envelope carrying no token — a failure wearing a success status. */
    refreshOmitsToken: boolean;
    /** Whether the protected route accepts {@link FRESH_TOKEN}; `false` makes the replay 401 too. */
    protectedAccepts: boolean;
}

/** @returns The scenario every case starts from: one refresh available, nothing accepted yet. */
const defaultScenario = (): Scenario => ({
    refreshBudget: 1,
    refreshOmitsToken: false,
    protectedAccepts: false
});

/** Requests seen by the server, in arrival order. Cleared before every case. */
let requestLog: LoggedRequest[] = [];

/** What the handlers answer with for the case currently running. */
let scenario: Scenario = defaultScenario();

/**
 * Builds the envelope the API rejects with, so the handlers and the app agree on one error shape.
 *
 * @param message - Human-readable reason, echoed into `errors` as the API does.
 * @returns A 401 response carrying the standard reject envelope.
 */
const unauthorized = (message: string) =>
    HttpResponse.json({ success: false, status: 401, message, errors: [message] }, { status: 401 });

const server = setupServer(
    /**
     * `GET /account/refresh` — succeeds while the budget lasts, then answers 401 like an expired
     * refresh cookie would.
     */
    http.get(`${API}/account/refresh`, ({ request }) => {
        requestLog.push({
            route: 'GET /account/refresh',
            authorization: request.headers.get('authorization') ?? undefined
        });

        if (scenario.refreshBudget <= 0) return unauthorized('Unauthorized');
        scenario.refreshBudget -= 1;

        return scenario.refreshOmitsToken
            ? HttpResponse.json({ success: true, status: 200, data: {} })
            : HttpResponse.json({ success: true, status: 200, data: { token: FRESH_TOKEN } });
    }),

    /**
     * `GET /orders` — the protected route the flow is triggered from. It answers 401 until it is
     * both told to accept and given the refreshed token, which is what makes the replay visible.
     */
    http.get(`${API}/orders`, ({ request }) => {
        const authorization = request.headers.get('authorization') ?? undefined;
        requestLog.push({ route: 'GET /orders', authorization });

        return scenario.protectedAccepts && authorization === `Bearer ${FRESH_TOKEN}`
            ? HttpResponse.json({ success: true, status: 200, data: { items: [] } })
            : unauthorized('Unauthorized');
    }),

    /** Every excluded path, each answering 401 as the ordinary outcome the exclusion exists for. */
    ...[...EXCLUDED_PATHS, ABSOLUTE_EXCLUDED_URL].map((path) =>
        http.post(path.startsWith('http') ? path : `${API}${path}`, ({ request }) => {
            requestLog.push({ route: `POST ${new URL(request.url).pathname}` });
            return unauthorized('Bad credentials');
        })
    )
);

/**
 * Imports the http plugin fresh, with the API base URL stubbed.
 *
 * The module builds its axios instance and registers its interceptors at import time, so the env
 * has to be in place first and the registry has to be reset between cases — otherwise the
 * interceptors stack up and one request runs the chain several times.
 *
 * @returns The freshly imported module, with `orvalMutator` and `getAccessToken` on it.
 */
const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return import('@/infrastructure/http');
};

/**
 * Clears the `isAuth` cookie through the prototype setter, the way `stores/session.ts` writes it.
 *
 * @returns Nothing; the cookie is cleared as a side effect.
 */
const clearAuthCookie = () =>
    Object.getOwnPropertyDescriptor(Document.prototype, 'cookie')?.set?.call(
        document,
        'isAuth=; path=/; max-age=0'
    );

/**
 * Every request the server saw, as `METHOD /pathname`.
 *
 * @returns The routes in arrival order — the sequence most assertions here are about.
 */
const routes = () => requestLog.map(({ route }) => route);

/**
 * How many times one route was requested.
 *
 * @param route - The `METHOD /pathname` to count.
 * @returns The number of matching requests the server saw.
 */
const timesRequested = (route: string) =>
    requestLog.filter((request) => request.route === route).length;

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    requestLog = [];
    scenario = defaultScenario();
    clearAuthCookie();
    vi.unstubAllEnvs();
});

describe('401 refresh flow', () => {
    describe('when the refresh succeeds', () => {
        beforeEach(() => {
            scenario.protectedAccepts = true;
        });

        it('refreshes once and replays the original request with the new token', () =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    orvalMutator<{ data: { items: unknown[] } }>({ url: '/orders', method: 'GET' })
                )
                .then((result) => {
                    expect(result.data.items).toEqual([]);
                    expect(routes()).toEqual([
                        'GET /orders',
                        'GET /account/refresh',
                        'GET /orders'
                    ]);
                    expect(requestLog.at(-1)?.authorization).toBe(`Bearer ${FRESH_TOKEN}`);
                }));

        it('stores the refreshed token, so later calls carry it', () =>
            loadHttp().then(({ orvalMutator, getAccessToken }) =>
                orvalMutator({ url: '/orders', method: 'GET' }).then(() => {
                    expect(getAccessToken()).toBe(FRESH_TOKEN);
                })
            ));

        /**
         * `setAccessToken` is the only writer of the JS-readable `isAuth` cookie, and
         * `tryRestoreAuth` reads it on the next boot: without it a signed-in visitor looks like a
         * guest after a reload.
         */
        it('restores the isAuth cookie, not just the in-memory token', () =>
            loadHttp()
                .then(({ orvalMutator }) => orvalMutator({ url: '/orders', method: 'GET' }))
                .then(() => {
                    expect(document.cookie).toContain('isAuth=true');
                }));
    });

    describe('when the refresh does not produce a usable token', () => {
        /**
         * A 200 whose envelope carries no token is a failed refresh wearing a success status. The
         * caller is owed either a body or a rejection; anything else surfaces as a `TypeError` in
         * whichever store dereferenced it, far from the interceptor that caused it.
         */
        it('rejects with the original error when the refresh answers 200 without a token', () => {
            scenario.refreshOmitsToken = true;

            return loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        success: false,
                        status: 401
                    })
                )
                .then(() => {
                    // Never replayed: there was no token to replay it with.
                    expect(timesRequested('GET /orders')).toBe(1);
                });
        });

        it('rejects with the original error when the refresh itself fails', () => {
            scenario.refreshBudget = 0;

            return loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        success: false,
                        status: 401
                    })
                )
                .then(() => {
                    expect(timesRequested('GET /orders')).toBe(1);
                });
        });

        /** `protectedAccepts` stays false, so the replayed request answers 401 as well. */
        it('does not retry a second time when the replay also fails', () =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        status: 401
                    })
                )
                .then(() => {
                    // One refresh and two /orders calls — `_dontRetry` stopped the loop.
                    expect(timesRequested('GET /account/refresh')).toBe(1);
                    expect(timesRequested('GET /orders')).toBe(2);
                }));
    });

    /**
     * Driven through `orvalMutator` against the real interceptor chain, and asserted on the
     * server's own request log — the only place a refresh attempt is observable without mocking
     * the very code under test.
     */
    describe('when the 401 comes from an excluded endpoint', () => {
        it.each([
            ...EXCLUDED_PATHS,
            ABSOLUTE_EXCLUDED_URL,
            // With a query string: the exclusion matches a PATHNAME, and `?next=` is the shape a
            // sign-in redirect actually arrives in.
            '/account/login?next=/cart'
        ])('never attempts a refresh for a 401 from %s', (url) =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url, method: 'POST', data: {} })).rejects.toMatchObject({
                        status: 401
                    })
                )
                .then(() => {
                    // The endpoint itself was reached...
                    expect(routes().some((route) => route.startsWith('POST '))).toBe(true);
                    // ...and no refresh was attempted off the back of its 401.
                    expect(timesRequested('GET /account/refresh')).toBe(0);
                })
        );
    });
});

tests/unit/app/app-navigation.spec.ts.source:
/**
 * App navigation.
 *
 * Beyond rendering, this pins the property that makes the menu trustworthy: an entry is shown
 * exactly when the router would let the visitor enter the route it points at. The nav reads
 * `meta.access` off the resolved route rather than carrying its own visibility flags, so the two
 * cannot drift — and these cases are what would catch it if someone reintroduced a flag.
 *
 * ── Why the modules here are invented ────────────────────────────────────────────────────────
 * `AppNavigation` builds its list from `collectModuleNavigation(enabledModules)`. Asserting
 * against the REAL registry would mean naming `products`, `cart`, `admin`… in a platform spec —
 * the exact coupling the manifest removed from `src/`, moved into `tests/`. Deleting a domain
 * would then break a test that is not about that domain at all (see `docs/theory/modules.md`,
 * "Deleting a domain").
 *
 * So `@/modules` is mocked with three throwaway domains covering the three visibility classes.
 * What is under test is the mechanism — filter by the resolved route's `meta.access`, order by
 * `order` — and the mechanism is what breaks. That every real module's entry points at a route it
 * actually declares is a separate, registry-driven invariant: `tests/cross-cutting/registry.spec.ts`.
 */
import { beforeEach, describe, it, expect, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { ref } from 'vue';
import { createPinia } from 'pinia';
import AppNavigation from '@/app/components/AppNavigation.vue';
import vuetify from '@/ui/vuetify';
import type { RouteAccess } from '@/app/guards/authentications';

const session = {
    isAuth: ref(false),
    isAdmin: ref(false),
    viewer: ref<{ email: string } | undefined>(undefined)
};

/**
 * Which of the auth routes this build ships.
 *
 * The shell addresses `Login` and `Signup` by name — strings the account module owns and nothing
 * type-checks — so it asks `router.hasRoute` before offering either. Flipping this to `false` is
 * the "no account module in this build" case.
 */
const registeredRoutes = ref<string[]>(['Login', 'Signup']);

/** The route the visitor is currently on, as `useRoute()` reports it. */
const currentRoute = ref<{ name?: string; fullPath: string }>({ fullPath: '/' });

/** Access declared by the routes the invented modules link to, plus the shell's own two. */
const routeAccess: Record<string, RouteAccess | undefined> = {
    Home: undefined,
    Playground: undefined,
    PublicThing: undefined,
    MemberThing: 'auth',
    StaffThing: 'admin'
};

/*
 * Three invented domains, one per visibility class. `order` is deliberately out of sequence so the
 * sort is exercised rather than accidentally satisfied by declaration order.
 */
vi.mock('@/modules', () => ({
    enabledModules: [
        {
            name: 'staff-domain',
            routes: [],
            navigation: [{ name: 'StaffThing', label: 'navigation.label-staff', order: 90 }]
        },
        {
            name: 'public-domain',
            routes: [],
            navigation: [{ name: 'PublicThing', label: 'navigation.label-public', order: 30 }]
        },
        {
            name: 'member-domain',
            routes: [],
            navigation: [{ name: 'MemberThing', label: 'navigation.label-member', order: 60 }]
        }
    ]
}));

vi.mock('vue-i18n', async (importOriginal) => {
    const actual = await importOriginal<typeof import('vue-i18n')>();
    return {
        ...actual,
        useI18n: () => ({
            t: (key: string) => key,
            locale: ref('en')
        })
    };
});

vi.mock('vue-router', () => ({
    RouterLink: {
        template: '<a><slot /></a>'
    },
    useRoute: () => ({ ...currentRoute.value, params: {}, query: {} }),
    useRouter: () => ({
        push: vi.fn(),
        replace: vi.fn(),
        resolve: ({ name }: { name: string }) => ({ meta: { access: routeAccess[name] } }),
        hasRoute: (name: string) => registeredRoutes.value.includes(name)
    })
}));

vi.mock('@/infrastructure/stores/session.ts', () => ({
    useSessionStore: () => session
}));

/** Mounts the nav and returns the labels of the entries it rendered. */
const mountNav = () => {
    const wrapper = mount(AppNavigation, {
        global: {
            plugins: [createPinia(), vuetify],
            stubs: {
                // v-app-bar teleports into a v-app layout that does not exist here
                VAppBar: {
                    template:
                        '<header><slot name="prepend" /><slot /><slot name="append" /></header>'
                },
                VNavigationDrawer: { template: '<aside><slot /></aside>' }
            }
        }
    });
    return { wrapper, text: wrapper.text() };
};

/**
 * Whether the app-bar button carrying `label` is `v-show`-hidden.
 *
 * `v-show` keeps the node in the DOM and sets `display: none`, so `wrapper.text()` cannot tell
 * the two states apart — the style is the only observable difference.
 */
const isHidden = (wrapper: ReturnType<typeof mountNav>['wrapper'], label: string) => {
    const button = wrapper
        .findAll('header button')
        .find((candidate) => candidate.text().includes(label));
    expect(button, `no app-bar button carrying ${label}`).toBeDefined();
    return (button!.element as HTMLElement).style.display === 'none';
};

describe('Navigation', () => {
    beforeEach(() => {
        session.isAuth.value = false;
        session.isAdmin.value = false;
        session.viewer.value = undefined;
        registeredRoutes.value = ['Login', 'Signup'];
        currentRoute.value = { fullPath: '/' };
    });

    it('renders properly', () => {
        expect(mountNav().wrapper).toBeTruthy();
    });

    it('shows a guest only the public entries', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-public');
        expect(text).not.toContain('navigation.label-member');
        expect(text).not.toContain('navigation.label-staff');
    });

    it('adds the authenticated entries once logged in, but not the admin ones', () => {
        session.isAuth.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-member');
        // The trap this guards: an admin-only page listed for every logged-in visitor.
        expect(text).not.toContain('navigation.label-staff');
    });

    it('shows the admin entries to an admin', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-staff');
        expect(text).toContain('navigation.label-member');
    });

    it('orders module entries by `order`, not by module registration order', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const { text } = mountNav();

        // staff-domain is registered first but ordered last.
        expect(text.indexOf('navigation.label-public')).toBeLessThan(
            text.indexOf('navigation.label-member')
        );
        expect(text.indexOf('navigation.label-member')).toBeLessThan(
            text.indexOf('navigation.label-staff')
        );
    });

    it('offers sign-in and sign-up when the account routes are registered', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-login');
        expect(text).toContain('navigation.label-signup');
    });

    /**
     * Hidden by ROUTE NAME, not by a substring of the path: a substring match also fires on
     * `/en/products/login-adapter` and on any `?continue=/en/login`.
     */
    it.each([
        ['Login', 'navigation.label-login'],
        ['Signup', 'navigation.label-signup']
    ])('hides the %s button while the visitor is already on that page', (name, label) => {
        currentRoute.value = { name, fullPath: `/en/${name.toLowerCase()}` };

        expect(isHidden(mountNav().wrapper, label)).toBe(true);
    });

    it('keeps both buttons on a route that merely CONTAINS the word login', () => {
        currentRoute.value = { name: 'ProductTarget', fullPath: '/en/products/login-adapter' };

        const { wrapper } = mountNav();

        expect(isHidden(wrapper, 'navigation.label-login')).toBe(false);
        expect(isHidden(wrapper, 'navigation.label-signup')).toBe(false);
    });

    it('offers neither when this build ships no sign-in route', () => {
        // A build with the account module deleted: the shell must not render a button that
        // navigates nowhere. Route names are strings, so only `hasRoute` can tell.
        registeredRoutes.value = [];

        const { text } = mountNav();

        expect(text).not.toContain('navigation.label-login');
        expect(text).not.toContain('navigation.label-signup');
    });

    it('renders the shell entries when no module contributes anything', () => {
        // The event-portal end state: every domain deleted, the shell still has a menu.
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-about');
    });
});

tests/unit/infrastructure/http/http.spec.source:
import { beforeAll, describe, expect, it, vi } from 'vitest';
import enMessages from '@/locales/en.json';

vi.mock('@/infrastructure/stores/session', () => ({
    useSessionStore: vi.fn(() => ({ accessToken: { value: undefined } }))
}));

vi.mock('pinia', () => ({
    storeToRefs: (store: { accessToken: { value: undefined } }) => store
}));

/**
 * Only `getCurrentLocale` is stubbed. `translate` is deliberately the REAL one, resolving against
 * the real vue-i18n instance: these assertions are about what a user is shown when the API sent
 * no message of its own, and a stubbed translator would make every language look the same.
 */
vi.mock('@/infrastructure/i18n', async (importOriginal) => ({
    ...(await importOriginal<typeof import('@/infrastructure/i18n')>()),
    getCurrentLocale: vi.fn(() => 'en')
}));

beforeAll(() => import('@/infrastructure/i18n').then(({ loadLocale }) => loadLocale('en')));

const makeAxiosError = (status: number, data: unknown, headers: Record<string, string> = {}) => ({
    response: { status, statusText: 'Error', data, headers },
    message: 'Request failed',
    config: { url: '/test' }
});

describe('onResponseReject', () => {
    it('passes through a standard reject envelope unchanged', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(400, {
                success: false,
                message: 'Bad',
                errors: ['field required']
            });
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                message: 'Bad',
                errors: ['field required']
            });
        });
    });

    it('enriches a reject envelope with x-request-id and x-trace-id headers', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(
                422,
                { success: false, message: 'Validation', errors: ['name required'] },
                { 'x-request-id': 'req-abc-123', 'x-trace-id': 'trace-xyz-789' }
            );
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                errors: ['name required'],
                requestId: 'req-abc-123',
                traceId: 'trace-xyz-789'
            });
        });
    });

    it('captures x-request-id on a fallback transport error', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(
                503,
                {},
                {
                    'x-request-id': 'req-fallback-1'
                }
            );
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                requestId: 'req-fallback-1'
            });
        });
    });

    it('normalizes 401 responses as authentication state errors', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(401, {});
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                status: 401,
                message: enMessages['api-errors'].unauthorized,
                errors: [enMessages['api-errors'].unauthorized]
            });
        });
    });

    it('normalizes 403 responses as authorization state errors', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = makeAxiosError(403, {});
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                success: false,
                status: 403,
                message: enMessages['api-errors'].forbidden,
                errors: [enMessages['api-errors'].forbidden]
            });
        });
    });

    it('omits requestId and traceId when headers are absent', () => {
        return import('@/infrastructure/http')
            .then(({ onResponseReject }) => {
                const error = makeAxiosError(500, {});
                return onResponseReject(error as never).catch((error_: unknown) => error_);
            })
            .then((result) => {
                expect(result).not.toHaveProperty('requestId');
                expect(result).not.toHaveProperty('traceId');
            });
    });
});

/**
 * The fallback branch of `onResponseReject` — everything that is *not* a well-formed reject
 * envelope from the API. That covers real transport failures (no response at all), gateway errors
 * from a proxy that never reached the app, and any 4xx the API answers without its envelope.
 *
 * The canonicalised messages matter because they are what a user sees: an axios `statusText` of
 * "" or a raw "Network Error" is not something to put in front of someone, and 5xx detail must
 * not leak server internals into the UI.
 */
describe('onResponseReject — fallback normalisation', () => {
    it('canonicalises any 5xx to a single safe message', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            return expect(onResponseReject(makeAxiosError(503, {}) as never)).rejects.toMatchObject(
                {
                    status: 503,
                    message: enMessages['api-errors']['internal-server-error']
                }
            );
        });
    });

    it('treats exactly 500 as a server error', () =>
        // The `>= 500` boundary. With `> 500` a plain 500 would fall through and surface the raw
        // statusText instead — the single most common server failure, mis-messaged.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(onResponseReject(makeAxiosError(500, {}) as never)).rejects.toMatchObject({
                message: enMessages['api-errors']['internal-server-error']
            })
        ));

    it('leaves a 4xx below the server range on its own message', () =>
        // The other side of the same boundary: 499 must NOT be canonicalised.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(onResponseReject(makeAxiosError(499, {}) as never)).rejects.toMatchObject({
                status: 499,
                message: 'Error'
            })
        ));

    it('carries no error items for a status that is neither 401 nor 403', () =>
        // 401/403 get a user-facing item because the UI renders them as a state change; other
        // fallbacks deliberately carry an empty list rather than echoing a transport string.
        import('@/infrastructure/http')
            .then(({ onResponseReject }) =>
                onResponseReject(makeAxiosError(404, {}) as never).catch(
                    (error_: unknown) => error_
                )
            )
            .then((result) => {
                expect((result as { errors: string[] }).errors).toEqual([]);
            }));

    it('falls back to status 500 when there is no response at all', () =>
        // A DNS failure, a refused connection, a CORS block: `error.response` is undefined, and
        // every call site still needs a status to branch on.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject({ message: 'Network Error', config: { url: '/x' } } as never)
            ).rejects.toMatchObject({ success: false, status: 500 })
        ));

    it('prefers statusText over the axios message', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = {
                response: { status: 418, statusText: "I'm a teapot", data: {}, headers: {} },
                message: 'Request failed',
                config: { url: '/x' }
            };
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                message: "I'm a teapot"
            });
        });
    });

    it('falls back to the axios message when statusText is empty', () =>
        // `||`, not `??`: axios sets `statusText` to '' rather than undefined on many adapters,
        // and an empty message would render as a blank error toast.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject({
                    response: { status: 418, statusText: '', data: {}, headers: {} },
                    message: 'Request failed',
                    config: { url: '/x' }
                } as never)
            ).rejects.toMatchObject({ message: 'Request failed' })
        ));

    it('falls back to a generic message when neither is available', () => {
        return import('@/infrastructure/http').then(({ onResponseReject }) => {
            const error = {
                response: { status: 418, statusText: '', data: {}, headers: {} },
                message: '',
                config: { url: '/x' }
            };
            return expect(onResponseReject(error as never)).rejects.toMatchObject({
                message: enMessages['api-errors'].unknown
            });
        });
    });

    it('passes an envelope through even when its errors list is empty', () =>
        // Detection is `hasOwnProperty('errors')`, not truthiness — an API reject that happens to
        // carry no items is still the API's own envelope and must not be re-synthesised.
        import('@/infrastructure/http').then(({ onResponseReject }) =>
            expect(
                onResponseReject(
                    makeAxiosError(422, {
                        success: false,
                        status: 422,
                        message: 'Validation failed',
                        errors: []
                    }) as never
                )
            ).rejects.toMatchObject({ message: 'Validation failed', errors: [] })
        ));
});

src/modules/account/tests/login-view-i18.source:
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { nextTick } from 'vue';
import { mount } from '@vue/test-utils';
import { createPinia } from 'pinia';
import Login from '@/modules/account/views/Login.vue';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import vuetify from '@/ui/vuetify';
import { usersSchema } from '@/modules/users';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';

/*
 * Login is account's view, but the field rules it renders are users' — so the expected copy is
 * derived by parsing with `usersSchema` itself, taken from the users **barrel**. That the two
 * modules agree on one set of rules is the point of `account`'s `dependsOn: ['users']`.
 *
 * Reading users' locale JSON directly would be quicker and is what this spec did at first; lint
 * rejected it, correctly — a sibling's dictionary is an internal, and `@/modules/users` is the
 * whole surface account is entitled to. Parsing through the schema is also the better assertion:
 * it compares the rendered text to what the schema actually produces, rather than to a file that
 * might not be the one loaded.
 *
 * The wiring below is what puts those keys into the i18n instance at all; without it every
 * assertion here would compare a rendered key against a translation.
 */
wireModulesIntoCore();

/** The message `usersSchema` produces for an invalid email, in whatever locale is active. */
const emailInvalidMessage = () => {
    const [message] = (
        usersSchema.safeParse({ email: 'nope', username: 'ada' }).error?.issues ?? []
    )
        .filter(({ path }) => path[0] === 'email')
        .map(({ message: text }) => text);
    // A raw key here would mean the dictionaries never loaded, which would make every
    // assertion below vacuously true.
    expect(message).not.toContain('users-form.');
    return message;
};

/**
 * One real view, end to end: the schema module, the composable, vue-i18n and the rendered
 * `v-text-field`. `tests/cross-cutting/schemas-i18n.spec.ts` proves the mechanism in isolation;
 * this proves a view is actually WIRED to it — `revalidateOn: locale` is easy to forget, and a
 * view that forgets it looks perfectly fine until someone switches language mid-form.
 *
 * vue-i18n is NOT mocked. A `t` stubbed to return its key would make both languages identical and
 * the assertion meaningless.
 */
vi.mock('vue-router', () => ({
    RouterLink: { template: '<a><slot /></a>' },
    useRoute: () => ({ fullPath: '/', params: {}, query: {} }),
    useRouter: () => ({ push: vi.fn(), replace: vi.fn() })
}));

const mountLogin = () =>
    mount(Login, {
        global: {
            plugins: [createPinia(), vuetify, i18n],
            stubs: {
                LayoutDefault: { template: '<div><slot /></div>' }
            }
        }
    });

const errorTexts = (wrapper: ReturnType<typeof mountLogin>) =>
    wrapper.findAll('.v-messages__message').map((node) => node.text());

describe('Login view, language switched mid-form', () => {
    beforeEach(() => loadLocale('en'));
    afterEach(() => loadLocale('en'));

    it('re-translates a displayed validation error', () => {
        let english = '';
        const wrapper = mountLogin();

        return wrapper
            .get('input[type="email"]')
            .setValue('not-an-email')
            .then(() => wrapper.get('form').trigger('submit'))
            .then(() => nextTick())
            .then(() => {
                english = emailInvalidMessage();
                expect(errorTexts(wrapper)).toContain(english);
                return loadLocale('it');
            })
            .then(() => nextTick())
            .then(() => {
                const italian = emailInvalidMessage();
                // Both halves matter: the Italian message is on screen AND the English one is
                // gone. Asserting only the first would pass on a field that renders both.
                expect(italian).not.toBe(english);
                expect(errorTexts(wrapper)).toContain(italian);
                expect(errorTexts(wrapper)).not.toContain(english);
            });
    });

    it('does not put errors on a pristine form just because the language changed', () => {
        const wrapper = mountLogin();

        return loadLocale('it')
            .then(() => nextTick())
            .then(() => {
                expect(errorTexts(wrapper)).toEqual([]);
            });
    });
});

tests/unit/ui/form-image-upload.spec.ts.source:
/**
 * `FormImageUpload.vue` — the component the plan ranks first by risk.
 *
 * `utils/uploads.ts` (the limits and the predicates) is well tested and now carries property
 * tests too. The component WRAPPING it was not tested at all, and the thing it owns is not
 * validation — it is a **resource**.
 *
 * `URL.createObjectURL` pins the picked blob in memory until `revokeObjectURL` releases it. The
 * component holds the URL in a ref precisely so it can revoke it, and there are three moments
 * where failing to do so leaks a whole image:
 *
 *   1. replacing one pick with another,
 *   2. clearing the field,
 *   3. unmounting while a file is picked.
 *
 * None of the three shows up as a failing assertion anywhere else, and none is visible in the UI
 * — it is a long editing session quietly holding a dozen images. So all three are asserted here
 * against a counted stub, which is the only way to see a revoke that did not happen.
 *
 * The other behaviours worth pinning are the two that a naive implementation gets backwards:
 * `progress === 0` must SHOW the bar (a request that has started and sent nothing) while
 * `undefined` hides it; and an array selection must be collapsed back into the model, because
 * every `imageUpload` field in the contract declares a single file.
 */
import { asStub } from '../../support/stub';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mount } from '@vue/test-utils';
import FormImageUpload from '@/ui/molecules/FormImageUpload.vue';
import vuetify from '@/ui/vuetify';
import { i18n } from '@/infrastructure/i18n';
import { ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE } from '@/infrastructure/utils/uploads';

/** Object-URL bookkeeping, so a missing revoke is observable. */
const created: string[] = [];
const revoked: string[] = [];

beforeEach(() => {
    created.length = 0;
    revoked.length = 0;
    let counter = 0;
    globalThis.URL.createObjectURL = vi.fn(() => {
        counter += 1;
        const url = `blob:mock/${counter}`;
        created.push(url);
        return url;
    });
    globalThis.URL.revokeObjectURL = vi.fn((url: string) => {
        revoked.push(url);
    });
});

afterEach(() => {
    vi.restoreAllMocks();
});

const makeFile = (name = 'photo.png', type = 'image/png') =>
    new File([new Uint8Array([1, 2, 3])], name, { type });

const mountUpload = (props: Record<string, unknown> = {}) =>
    mount(FormImageUpload, {
        props,
        global: { plugins: [vuetify, i18n] }
    });

describe('FormImageUpload — the object-URL resource', () => {
    it('mints exactly one object URL for a picked file', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(1);
    });

    it('revokes the previous URL when the pick is REPLACED', async () => {
        // The leak that is easiest to miss: clearing is usually handled, replacing is not.
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile('first.png') });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: makeFile('second.png') });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(2);
        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL when the field is cleared', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL on unmount, rather than leaking it with the component', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        wrapper.unmount();

        expect(revoked).toContain(created[0]);
    });

    it('revokes nothing when nothing was ever picked', () => {
        // `releaseObjectUrl` guards on the ref; without the guard this revokes `undefined`.
        mountUpload().unmount();

        expect(revoked).toHaveLength(0);
    });
});

describe('FormImageUpload — the preview', () => {
    it('shows the existing image while nothing is picked', () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        expect(wrapper.find('img').attributes('src')).toBe('/images/existing.png');
    });

    it('prefers the picked file over the existing image', async () => {
        // An edit form must not keep showing the old picture after the user chose a new one.
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe(created[0]);
    });

    it('renders no image at all when there is neither', () => {
        expect(mountUpload().find('img').exists()).toBe(false);
    });

    it('falls back to the existing image again once the pick is cleared', async () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe('/images/existing.png');
    });
});

/*
 * Selected by `data-testid`, never by `.v-progress-linear`: Vuetify's `v-file-input` renders its
 * own progress bar inside the field loader, so the class matches even when this component's bar
 * is absent — a spec written against it passes in both states and asserts nothing.
 */
describe('FormImageUpload — the progress bar', () => {
    it('is hidden while no upload is running', () => {
        expect(mountUpload().find('[data-testid=upload-progress]').exists()).toBe(false);
    });

    it('is SHOWN at zero percent, which is not the same as idle', async () => {
        // The distinction the component exists to make: `undefined` is idle, `0` is a request
        // that has started and sent nothing yet. A truthiness check collapses the two.
        const wrapper = mountUpload({ progress: 0 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('is shown while an upload is in flight', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('rounds a fractional percentage', async () => {
        // Asserted on `aria-valuenow` rather than on the visible label, for two reasons: it is
        // what a screen reader actually announces, and the label is an i18n message whose
        // dictionary is lazily loaded, so in a unit test it renders as the raw key.
        const wrapper = mountUpload({ progress: 42.6 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '43'
        );
    });

    it('reports the exact percentage when it is already whole', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '42'
        );
    });
});

describe('FormImageUpload — the field', () => {
    it('restricts the picker to the types the backend accepts', () => {
        // The picker's filter and the validation rule are both derived from ACCEPTED_IMAGE_TYPES
        // so they cannot disagree; this pins that the derivation actually reaches the DOM.
        expect(mountUpload().find('input[type=file]').attributes('accept')).toBe(
            ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE
        );
    });

    it('surfaces validation errors passed by the form', async () => {
        const wrapper = mountUpload({ errorMessages: ['File is too large'] });
        await wrapper.vm.$nextTick();

        expect(wrapper.text()).toContain('File is too large');
    });

    it('disables the picker while the form is submitting', () => {
        expect(
            mountUpload({ disabled: true }).find('input[type=file]').attributes('disabled')
        ).toBeDefined();
    });

    it('collapses an array selection back to a single file', async () => {
        // Vuetify types VFileInput's model as `File | File[] | null` because one component covers
        // the `multiple` case. Every `imageUpload` field in the contract is a single file, so an
        // array reaching the parent would be a contract violation.
        const wrapper = mountUpload();
        const file = makeFile();

        await wrapper.setProps({ modelValue: asStub<File>([file]) });
        await wrapper.vm.$nextTick();

        const emitted = wrapper.emitted('update:modelValue');
        expect(emitted?.at(-1)?.[0]).toBe(file);
    });
});

