/**
 * The shared axios instance's configuration — `src/infrastructure/http/client.ts`.
 *
 * Both defaults are read from the environment at import time and both have a fallback, which is
 * exactly the shape that goes wrong silently: a missing `VITE_API_URL` that resolved to
 * `undefined` would make every relative call hit the dev server instead of the API, and a
 * missing timeout would make a hung request hang forever. So each arm is loaded on its own.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';

/**
 * Imports the client fresh, so the module-scope env reads run again.
 *
 * @param environment - Variables to stub before the import; anything omitted is unset.
 * @returns The freshly imported module.
 */
const loadClient = (environment: Record<string, string | undefined>) => {
    vi.resetModules();
    for (const [key, value] of Object.entries(environment))
        if (value === undefined) vi.stubEnv(key, undefined);
        else vi.stubEnv(key, value);
    return import('@/infrastructure/http/client.ts');
};

afterEach(() => {
    vi.unstubAllEnvs();
});

describe('axios instance defaults', () => {
    it('takes the base URL and timeout from the environment', () => {
        return loadClient({ VITE_API_URL: 'http://api.test', VITE_AXIOS_TIMEOUT: '2500' }).then(
            ({ instance }) => {
                expect(instance.defaults.baseURL).toBe('http://api.test');
                expect(instance.defaults.timeout).toBe(2500);
            }
        );
    });

    it('falls back to same-origin relative calls and a ten second timeout', () => {
        return loadClient({ VITE_API_URL: undefined, VITE_AXIOS_TIMEOUT: undefined }).then(
            ({ instance }) => {
                // Empty string, not undefined: axios treats an undefined baseURL as "no prefix",
                // which is the same result by accident rather than by decision.
                expect(instance.defaults.baseURL).toBe('');
                expect(instance.defaults.timeout).toBe(10_000);
            }
        );
    });

    it('sends credentials, so the httpOnly refresh cookie travels with every call', () => {
        return loadClient({}).then(({ instance }) => {
            expect(instance.defaults.withCredentials).toBe(true);
        });
    });
});

tests/unit/infrastructure/i18n/i18n.spec.source:
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { createI18n } from 'vue-i18n';
import type { TranslationDictionaries } from '@/infrastructure/i18n';
import {
    getCurrentLocale,
    getDefaultLocale,
    loadedLanguages,
    _changeLanguage,
    _ensureFallbackLoaded,
    _loadLocale,
    _updateLocale,
    i18n,
    loadBundledDictionary,
    registerLocaleContributors
} from '@/infrastructure/i18n';
import { routerLinkI18n } from '@/infrastructure/i18n/router-link.ts';
import enMessages from '@/locales/en.json';
import itMessages from '@/locales/it.json';

/**
 * The locale machinery itself, against a REAL vue-i18n instance.
 *
 * The other locale spec, `tests/unit/app/guards/locale-choice.spec.ts`, mocks
 * `@/infrastructure/i18n` wholesale: it asserts that `changeLanguage` *was called with* `'it'` and
 * never that anything became Italian. That is the right way to test a router guard, and it leaves
 * everything underneath to this file.
 *
 * The `_`-prefixed functions take the instance to act on, which is exactly so a test can use a
 * throwaway one instead of mutating the app-wide singleton. `supportedLanguages` and
 * `loadedLanguages` are module state shared with that singleton, so anything touching them is
 * restored afterwards.
 */

const freshInstance = () => createI18n({ legacy: false, locale: 'en', fallbackLocale: 'en' });

/** Restores `loadedLanguages` to whatever it held before a test pushed to it. */
const withLoadedLanguagesRestored = () => {
    const snapshot = [...loadedLanguages];
    return () => loadedLanguages.splice(0, Number.POSITIVE_INFINITY, ...snapshot);
};

describe('supportedLanguages', () => {
    afterEach(() => {
        vi.resetModules();
    });

    /**
     * The folder IS the declaration. There is no env list any more: naming a language in `.env`
     * claimed support without supplying anything able to render it, and `mergeRemoteLocales` is
     * what adds the ones only the API knows about.
     */
    it('is every dictionary in src/locales, and nothing else', () => {
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            // The glob sees the real directory: en.json and it.json ship, es.json deliberately
            // does not — it is the language the API supplies at runtime.
            expect(reloaded.supportedLanguages).toEqual(['en', 'it']);
        });
    });

    /**
     * The supported/loaded split, and the reason the list is mutable: a language can be OFFERED
     * before its dictionary is anywhere near the bundle. `mergeRemoteLocales` pushes onto this
     * array at boot, and every module that imported the binding sees the addition.
     */
    it('accepts a locale with no local dictionary being added at runtime', () => {
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            reloaded.supportedLanguages.push('es');
            expect(reloaded.supportedLanguages).toContain('es');
        });
    });
});

describe('_loadLocale', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    it('imports and activates a supported locale that is not loaded yet', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.locale.value).toBe('it');
            expect(loadedLanguages).toContain('it');
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('short-circuits when the locale is already loaded', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'it');
        // Registered by hand rather than imported: if the short circuit is broken and the real
        // file is fetched, this sentinel is overwritten and the assertion fails.
        instance.global.setLocaleMessage('it', { sentinel: 'not-from-the-file' });
        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('sentinel')).toBe('not-from-the-file');
            expect(instance.global.locale.value).toBe('it');
        });
    });

    it('falls back to the default locale for an unsupported one', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _loadLocale(instance, 'kl').then(() => {
            expect(instance.global.locale.value).toBe(getDefaultLocale());
        });
    });

    /**
     * `es` is supported but has no file, so the dynamic import rejects. The documented contract
     * is that this degrades to the default locale rather than rejecting: callers have no
     * `.catch`, and a failed dictionary must never strand a navigation.
     */
    it('falls back to the default locale when the import fails', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return expect(_loadLocale(instance, 'es'))
            .resolves.not.toThrow()
            .then(() => {
                expect(instance.global.locale.value).toBe(getDefaultLocale());
            });
    });
});

describe('_updateLocale', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    it('registers a dictionary fetched from somewhere other than the bundle', () => {
        const instance = freshInstance();
        return _updateLocale(instance, 'es', { greeting: 'Hola' }).then(() => {
            instance.global.locale.value = 'es';
            expect(instance.global.t('greeting')).toBe('Hola');
            expect(loadedLanguages).toContain('es');
        });
    });

    it('overwrites an existing dictionary without duplicating the loaded entry', () => {
        const instance = freshInstance();
        return _updateLocale(instance, 'es', { greeting: 'Hola' })
            .then(() => {
                return _updateLocale(instance, 'es', { greeting: 'Buenas' });
            })
            .then(() => {
                instance.global.locale.value = 'es';
                expect(instance.global.t('greeting')).toBe('Buenas');
                expect(loadedLanguages.filter((locale) => locale === 'es')).toHaveLength(1);
            });
    });
});

describe('_changeLanguage', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    /**
     * `<html lang>` is not decoration: it tells screen readers which pronunciation rules to use
     * and browsers whether to offer a translation. Nothing else in the app sets it.
     */
    it('keeps <html lang> in sync', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'it');
        return _changeLanguage(instance, 'it').then(() => {
            expect(document.documentElement.getAttribute('lang')).toBe('it');
        });
    });

    /**
     * `fallbackLocale` is inert unless the fallback's messages are registered. Without loading
     * it, landing directly on a locale this app has no dictionary for leaves EVERY UI key
     * rendering as its own raw identifier — there is nothing to fall back to.
     */
    it('loads the fallback dictionary too, so per-key fallback actually works', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);

        // A locale with no local dictionary — the API-only case.
        return _updateLocale(instance, 'es', { api: { greeting: 'Hola' } })
            .then(() => _changeLanguage(instance, 'es'))
            .then(() => {
                expect(instance.global.locale.value).toBe('es');
                expect(loadedLanguages).toContain('en');
                // Falls through to the English copy rather than echoing the key back.
                expect(instance.global.t('navigation.error-already-logged')).toBe(
                    enMessages.navigation['error-already-logged']
                );
            });
    });

    it('does not try to load the fallback when it is the locale being activated', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'en');
        return expect(_ensureFallbackLoaded(instance, 'en')).resolves.toBeUndefined();
    });

    it('loads the dictionary first when the locale has never been loaded', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _changeLanguage(instance, 'it').then(() => {
            expect(instance.global.locale.value).toBe('it');
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });
});

describe('getDefaultLocale', () => {
    afterEach(() => {
        vi.unstubAllGlobals();
        vi.unstubAllEnvs();
        vi.resetModules();
    });

    it('uses the browser language when it is supported', () => {
        vi.stubGlobal('navigator', { language: 'it-IT' });
        expect(getDefaultLocale()).toBe('it');
    });

    it('falls back when the browser language is not supported', () => {
        vi.stubGlobal('navigator', { language: 'kl-GL' });
        expect(getDefaultLocale()).toBe('en');
    });

    /**
     * The check is against SUPPORTED, not loaded, languages. On a first visit nothing is loaded
     * yet, so a `loadedLanguages` check would never match and browser detection would be dead
     * code that always returned the fallback.
     */
    it('matches a browser language whose dictionary is not loaded yet', () => {
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            // As `mergeRemoteLocales` would have left it after a boot against a live API.
            reloaded.supportedLanguages.push('es');
            vi.stubGlobal('navigator', { language: 'es-ES' });
            expect(reloaded.getDefaultLocale()).toBe('es');
        });
    });
});

describe('routerLinkI18n', () => {
    beforeEach(() => {
        i18n.global.locale.value = 'en';
    });

    it('prefixes a plain path string', () => {
        expect(routerLinkI18n('/products')).toBe('/en/products');
    });

    it('normalises a relative path', () => {
        expect(routerLinkI18n('products')).toBe('/en/products');
    });

    it('leaves an already-prefixed path alone', () => {
        expect(routerLinkI18n('/it/products')).toBe('/it/products');
    });

    it('prefixes the path of a path-based location object', () => {
        expect(routerLinkI18n({ path: '/products', query: { page: '2' } })).toEqual({
            path: '/en/products',
            query: { page: '2' }
        });
    });

    it('injects the locale into params for a named location', () => {
        expect(routerLinkI18n({ name: 'Products' })).toEqual({
            name: 'Products',
            params: { locale: 'en' }
        });
    });

    it('lets an explicit params.locale win', () => {
        expect(routerLinkI18n({ name: 'Products', params: { locale: 'it' } })).toEqual({
            name: 'Products',
            params: { locale: 'it' }
        });
    });

    /**
     * The documented trap: vue-router IGNORES `params` whenever `path` is present. So a
     * `path`-based location must have the locale put into the path itself — injecting
     * `params.locale` would be silently dropped, and a bare `/products` would then match
     * `/:locale` with `locale = "products"`.
     */
    it('does not try to use params for a path-based location', () => {
        const result = routerLinkI18n({ path: '/products' }) as { path: string; params?: unknown };

        expect(result.path).toBe('/en/products');
        expect(result.params).toBeUndefined();
    });

    it('follows the active locale', () => {
        // Synchronous: nothing here awaited anything, the `async` was vestigial.
        i18n.global.locale.value = 'it';
        expect(routerLinkI18n('/products')).toBe('/it/products');
        expect(getCurrentLocale()).toBe('it');
    });
});

/**
 * Module-load-time branches.
 *
 * `supportedLanguages` and the empty-list guard are evaluated once, when the module is first
 * imported, from `import.meta.env`. They cannot be reached by calling anything — only by
 * re-importing the module under different env, which is what `resetModules` + `stubEnv` do here.
 *
 * Worth the machinery because both branches are failure-mode code: one is how the app discovers
 * its locales when no env list is configured, the other is what keeps it from booting with an
 * empty language list. Neither had ever been executed by a test.
 */
describe('module-load configuration', () => {
    afterEach(() => {
        vi.resetModules();
    });

    /**
     * The glob is evaluated once, when the module is first imported, and cannot be reached by
     * calling anything — only by re-importing, which is what `resetModules` does here.
     *
     * Worth the machinery because this is the offline floor: it is what the app offers when the
     * API cannot be reached at all, and nothing else in the suite executes the discovery.
     */
    it('discovers the bundled locales from the folder', () => {
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).toContain('en');
            expect(reloaded.supportedLanguages).toContain('it');
            expect(reloaded.supportedLanguages).not.toContain('es');
        });
    });

    /**
     * A fresh copy per import, not the glob's own array. `mergeRemoteLocales` mutates this list,
     * so a shared reference would carry one test's runtime additions into the next.
     */
    it('hands out a list that can be extended without affecting the next import', () => {
        vi.resetModules();
        return import('@/infrastructure/i18n')
            .then((first) => {
                first.supportedLanguages.push('es');
                vi.resetModules();
                return import('@/infrastructure/i18n');
            })
            .then((second) => {
                expect(second.supportedLanguages).not.toContain('es');
            });
    });
});

/**
 * The one custom message modifier the dictionaries actually use — `it.json`'s
 * `products-list-page.modified-products-list` is `@.customSnakeCase:{'generic.product'}`.
 */
describe('the customSnakeCase modifier', () => {
    it('joins a linked message’s words with underscores', () => {
        return _updateLocale(i18n, 'en', {
            ...(enMessages as TranslationDictionaries),
            ['modifier-probe']: "@.customSnakeCase:{'modifier-source'}",
            ['modifier-source']: 'two words'
        }).then(() => {
            i18n.global.locale.value = 'en';
            expect(i18n.global.t('modifier-probe')).toBe('two_words');
            return _updateLocale(i18n, 'en', enMessages);
        });
    });
});

/**
 * Dictionary merging — locales merge at boot, not at build.
 *
 * Each module ships its own `locales/{en,it}.json` and registers a loader for it; `_loadLocale`
 * pulls the shared file plus every registered loader and merges them into one locale. The merge
 * has to be DEEP, because several modules each contribute a slice of the same `navigation`
 * namespace — a shallow merge would leave the last writer's slice and silently drop the rest,
 * which looks exactly like a missing translation and not at all like a bug in the loader.
 *
 * Synthetic contributors rather than the real modules: this is core, and which domains exist is
 * not its business. `cross-cutting/schemas-i18n.spec.ts` is where the real dictionaries are swept.
 */
describe('registerLocaleContributors', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });

    afterEach(() => {
        restore();
        // Module state shared with the app-wide singleton — leave it as it was found.
        registerLocaleContributors({});
    });

    it('merges a contributed dictionary on top of the shared one', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Titolo' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('madeUpPage.title')).toBe('Titolo');
            // and the shared dictionary is still there
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('deep-merges two contributors into one shared namespace', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [
                () => Promise.resolve({ navigation: { labelAlpha: 'Alfa' } }),
                () => Promise.resolve({ navigation: { labelBeta: 'Beta' } })
            ]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('navigation.labelAlpha')).toBe('Alfa');
            expect(instance.global.t('navigation.labelBeta')).toBe('Beta');
            // the shared file's own entries under the same namespace survive both
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('ignores contributors registered for a different locale', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            en: [() => Promise.resolve({ madeUpPage: { title: 'Title' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.te('madeUpPage.title', 'it')).toBe(false);
        });
    });

    it('replaces the previous registration instead of accumulating', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'First' } })]
        });
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Second' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('madeUpPage.title')).toBe('Second');
        });
    });

    /**
     * The regression this whole block exists for.
     *
     * The running app does NOT reach a first locale through `_loadLocale`. `localeChoice`, the
     * router guard, builds the dictionary itself (bundled file + the API's overrides on top) and
     * installs it with `updateLocale`. When the module merge lived in `_loadLocale` only, every
     * unit test passed and the browser rendered `products-list-page.title` as its own key on the
     * very first navigation — 24 e2e failures, all of them module-owned copy.
     *
     * So the merge belongs at the install point. This asserts the guard's path specifically.
     */
    it('merges contributors when a locale is installed via _updateLocale, not just _loadLocale', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Titolo' } })]
        });

        // Exactly what `localeChoice` does: hand over an already-assembled dictionary.
        return _updateLocale(instance, 'it', {
            navigation: { ['error-already-logged']: 'Sei già loggato' },
            api: {}
        }).then(() => {
            instance.global.locale.value = 'it';
            expect(instance.global.t('madeUpPage.title')).toBe('Titolo');
            // and the caller's own dictionary survived the merge
            expect(instance.global.t('navigation.error-already-logged')).toBe('Sei già loggato');
        });
    });

    it('loads the shared dictionary alone when no module contributes', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({});

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });
});

describe('loadBundledDictionary', () => {
    afterEach(() => registerLocaleContributors({}));

    it('merges the shared file with every module slice, without touching the instance', () => {
        registerLocaleContributors({
            it: [() => Promise.resolve({ navigation: { 'label-extra': 'Extra' } })]
        });
        const before = i18n.global.getLocaleMessage('it');
        return loadBundledDictionary('it').then((dictionary) => {
            const navigation = dictionary.navigation as Record<string, string>;
            // The shared file's keys survive beside the module's: a deep merge, not a replace.
            expect(navigation['error-already-logged']).toBe(
                itMessages.navigation['error-already-logged']
            );
            expect(navigation['label-extra']).toBe('Extra');
            expect(i18n.global.getLocaleMessage('it')).toEqual(before);
        });
    });

    it('answers an empty dictionary for a language this build does not ship', () =>
        loadBundledDictionary('kl').then((dictionary) => {
            expect(dictionary).toEqual({});
        }));

    it('never mutates the imported file object', () => {
        registerLocaleContributors({ en: [() => Promise.resolve({ generic: { probe: 'x' } })] });
        return loadBundledDictionary('en').then(() => {
            expect((enMessages.generic as Record<string, string>).probe).toBeUndefined();
        });
    });
});

tests/unit/infrastructure/utils/formatte.source:
/**
 * Property-based tests — `src/infrastructure/formatters.ts` and `src/infrastructure/uploads.ts`.
 *
 * The example-based suites next door assert what these functions do for the inputs someone
 * thought of. These assert what must hold for EVERY input, which is a different question and
 * catches a different class of bug: the boundary nobody enumerated, the surrogate pair, the
 * `-0`, the string that is whitespace in a script you have never seen.
 *
 * Why this layer exists at all: it is the general form of a fix this repo already paid for the
 * expensive way. `response-schema-map.ts` was tested by sampling a handful of rows from a 52-row
 * table and scored 55% mutation with 182 survivors in that one file; replacing the sample with
 * exhaustive generation took it to ~96% and the whole suite from 55% to 81%. Sampling a space
 * you could have covered is the failure mode, and generation is the answer to it.
 *
 * TWO RULES, both non-negotiable and both about determinism:
 *
 *   1. **Every run is seeded.** `fast-check` defaults to a random seed, which makes a failure
 *      un-reproducible and — worse — makes a test that fails one run in fifty look like flake.
 *      A fixed seed means this suite either passes or fails, the same way every other test does.
 *   2. **Every counterexample becomes a regression case**, written out as an ordinary `it()` with
 *      the seed that found it in a comment. The property stays as the general statement; the
 *      example stays as the thing that once broke.
 *
 * `numRuns` is deliberately modest. These run on the pre-commit path, where the frontend gate is
 * already ~8.5 minutes; a property that needs ten thousand cases to find its bug is a property
 * that wants a nightly, not a commit hook.
 *
 * ── SPLIT WITH `formatters.spec.ts` / `uploads.spec.ts` ─────────────────────────────────────
 * Those files are example-based and own the SPECIFIC values: the exact size boundary, the
 * non-canonical `image/jpg`, the shipped copy of a message. This file owns what only generation
 * can claim — that a rule holds for EVERY input, not for the ones someone thought of.
 *
 * Check there before adding a case here. A fact asserted twice is maintained twice.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';
import {
    EMPTY_VALUE,
    formatCurrency,
    formatFlag,
    formatText,
    formatDateTime,
    formatDate
} from '@/infrastructure/utils/formatters';
import {
    ACCEPTED_IMAGE_TYPES,
    MAX_UPLOAD_BYTES,
    formatUploadSize,
    isAcceptedImageType,
    isWithinUploadSizeLimit
} from '@/infrastructure/utils/uploads';

/**
 * One seed for the whole file, and one place to change it.
 *
 * `endOnFailure` trims the shrunk counterexample instead of continuing to shrink for a while
 * after it has one, which keeps a failure message short enough to paste into a regression case.
 */
const RUN = { seed: 20_260_808, numRuns: 200, endOnFailure: true } as const;

/**
 * The two nullish spellings these signatures actually accept.
 *
 * `formatText(value?: string | null)`, `formatCurrency(value?: number | null)` and
 * `formatFlag(value: boolean | null | undefined, …)` all admit both, and the properties below
 * depend on both taking the fallback branch — so neither can be dropped to satisfy a lint rule
 * that would rather this codebase had only `undefined`.
 */
const nullish = () => fc.constantFrom(null, undefined);

/** The locale the formatters read. Pinned so a machine's locale cannot decide the assertions. */
vi.mock('@/infrastructure/i18n', () => ({
    getCurrentLocale: () => 'en'
}));

beforeEach(() => {
    vi.clearAllMocks();
});

describe('formatText', () => {
    it('never returns an empty or blank string, for any input', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                const result = formatText(value);
                // The whole purpose of the function: a table cell always has something in it.
                expect(result.trim().length).toBeGreaterThan(0);
            }),
            RUN
        ));

    it('returns the fallback for exactly the inputs that carry no text', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // A biconditional, not two separate cases: this is the whole decision rule, and
                // asserting it both ways is what stops the boundary drifting in one direction.
                const isBlank = value === undefined || value.trim().length === 0;
                expect(formatText(value) === EMPTY_VALUE).toBe(isBlank || value === EMPTY_VALUE);
            }),
            RUN
        ));

    it('returns non-blank input UNCHANGED, rather than trimmed', () =>
        fc.assert(
            fc.property(fc.string({ minLength: 1 }), (value) => {
                fc.pre(value.trim().length > 0);
                // The emptiness test trims; the return value does not. A refactor that returned
                // `value.trim()` would pass every "is it non-empty" assertion above.
                expect(formatText(` ${value} `)).toBe(` ${value} `);
            }),
            RUN
        ));

    it('is idempotent', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                expect(formatText(formatText(value))).toBe(formatText(value));
            }),
            RUN
        ));
});

describe('formatCurrency', () => {
    it('returns the fallback for every non-number, and never for a number', () =>
        fc.assert(
            fc.property(
                fc.oneof(
                    fc.double({ noNaN: true, noDefaultInfinity: true }),
                    nullish(),
                    fc.string(),
                    fc.boolean()
                ),
                (value) => {
                    const result = formatCurrency(value as number | null | undefined);
                    expect(result === EMPTY_VALUE).toBe(typeof value !== 'number');
                }
            ),
            RUN
        ));

    it('never throws, for any amount and any currency code', () =>
        fc.assert(
            fc.property(
                fc.double({ noNaN: true, noDefaultInfinity: true }),
                fc.string(),
                (value, currency) => {
                    // The `catch` in formatCurrency exists for exactly this: an unknown or
                    // malformed ISO 4217 code makes Intl throw a RangeError, and a product page
                    // must not 500 over a currency string. Generation is what reaches the codes
                    // nobody would think to write down.
                    expect(() => formatCurrency(value, currency)).not.toThrow();
                }
            ),
            RUN
        ));

    it('degrades to a plain number rather than the fallback on a bad currency', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                // The failure path must still show the AMOUNT. Returning EMPTY_VALUE here would
                // hide a real price behind an em dash because of a config typo.
                expect(formatCurrency(value, 'not-a-currency')).not.toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('renders every finite amount with at least one digit', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                expect(formatCurrency(value)).toMatch(/\d/);
            }),
            RUN
        ));
});

describe('formatFlag', () => {
    it('returns one of exactly three things, and the fallback only for nullish', () =>
        fc.assert(
            fc.property(
                fc.option(fc.boolean(), { nil: undefined }),
                fc.string(),
                fc.string(),
                (value, trueLabel, falseLabel) => {
                    // The expected value is computed first and asserted once, rather than
                    // branching around two `expect`s — same property, but it states the whole
                    // decision rule as one expression.
                    //
                    // `false` is the classic place this breaks: a `!value` guard would send it
                    // down the fallback branch alongside null and undefined.
                    const expected =
                        value === undefined ? EMPTY_VALUE : value ? trueLabel : falseLabel;

                    expect(formatFlag(value, trueLabel, falseLabel)).toBe(expected);
                }
            ),
            RUN
        ));
});

describe('formatDateTime', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // The value comes off the wire. An unparseable one yields "Invalid Date", which
                // is ugly but must not be an exception in a render.
                expect(() => formatDateTime(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDateTime(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));
});

describe('formatDate', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // Same contract as `formatDateTime`: off-the-wire input, never an exception mid-render.
                expect(() => formatDate(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDate(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('is never longer than the datetime it drops the time from', () =>
        fc.assert(
            fc.property(fc.date({ noInvalidDate: true }), (date) => {
                const iso = date.toISOString();
                expect(formatDate(iso).length).toBeLessThanOrEqual(formatDateTime(iso).length);
            }),
            RUN
        ));
});

/** A File whose `type` and `size` are the only fields the upload predicates read. */
const makeFile = (type: string, size: number) => ({ type, size }) as File;

describe('upload predicates', () => {
    it('accepts a type if and only if it is on the shared list', () =>
        fc.assert(
            fc.property(fc.string(), fc.nat(), (type, size) => {
                expect(isAcceptedImageType(makeFile(type, size))).toBe(
                    (ACCEPTED_IMAGE_TYPES as readonly string[]).includes(type)
                );
            }),
            RUN
        ));

    it('is case-sensitive about the mime type, matching the backend', () =>
        fc.assert(
            fc.property(fc.constantFrom(...ACCEPTED_IMAGE_TYPES), (type) => {
                // Documented rather than assumed: the backend's fileFilter compares verbatim, so
                // a client-side check that lowercased first would accept files the server then
                // rejects — a worse experience than rejecting early.
                expect(isAcceptedImageType(makeFile(type.toUpperCase(), 1))).toBe(false);
            }),
            RUN
        ));

    it('treats the size limit as inclusive, on both sides of the boundary', () =>
        fc.assert(
            fc.property(fc.nat(), (size) => {
                expect(isWithinUploadSizeLimit(makeFile('image/png', size))).toBe(
                    size <= MAX_UPLOAD_BYTES
                );
            }),
            RUN
        ));

    /*
     * The exact boundary — `MAX_UPLOAD_BYTES` and one byte over — is NOT asserted here. It is
     * already an example in `uploads.spec.ts` ("accepts a file of exactly the limit and rejects
     * one byte more"), and restating it was a straight duplicate. The property above covers the
     * whole range; that one pins the single value `fc.nat()` would only reach by luck.
     */

    it('renders every size as a positive-looking MB label', () =>
        fc.assert(
            fc.property(fc.nat(), (bytes) => {
                const label = formatUploadSize(bytes);
                expect(label).toMatch(/^\d+(\.\d)? MB$/);
                // `Number(...toFixed(1))` drops a trailing ".0", which is the whole reason the
                // conversion is written that way — "5 MB", not "5.0 MB".
                expect(label).not.toMatch(/\.0 MB$/);
            }),
            RUN
        ));

    it('is monotonic in bytes', () =>
        fc.assert(
            fc.property(fc.nat(), fc.nat(), (a, b) => {
                fc.pre(a < b);
                const sizeA = Number.parseFloat(formatUploadSize(a));
                const sizeB = Number.parseFloat(formatUploadSize(b));
                // Rounding may make them equal; it must never invert them.
                expect(sizeA).toBeLessThanOrEqual(sizeB);
            }),
            RUN
        ));
});

