/**
 * Display formatters.
 *
 * Written because the first mutation run scored this file 0%: every one of its mutants survived,
 * since nothing in the suite called it at all. These are the functions every detail page renders
 * through, and each one has a fallback branch that only shows up when data is missing — which is
 * exactly the case nobody clicks through by hand.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
    EMPTY_VALUE,
    formatText,
    formatDate,
    formatDateTime,
    formatCurrency,
    formatFlag,
    formatMegabytes,
    formatTime,
    formatUptime
} from '@/infrastructure/utils/formatters';

describe('formatText', () => {
    it('returns the text unchanged when it has content', () => {
        expect(formatText('Gadget')).toBe('Gadget');
    });

    it('falls back for undefined, null and empty strings', () => {
        expect(formatText()).toBe(EMPTY_VALUE);
        expect(formatText(null)).toBe(EMPTY_VALUE);
        expect(formatText('')).toBe(EMPTY_VALUE);
    });

    it('treats whitespace-only text as empty', () => {
        expect(formatText('   ')).toBe(EMPTY_VALUE);
    });

    it('keeps surrounding whitespace on text that is not blank', () => {
        expect(formatText('  Gadget  ')).toBe('  Gadget  ');
    });
});

describe('formatDateTime', () => {
    it('formats an ISO datetime into a localized string', () => {
        const formatted = formatDateTime('2026-08-05T10:30:00.000Z');

        expect(formatted).not.toBe(EMPTY_VALUE);
        expect(formatted).toContain('2026');
    });

    it('falls back for undefined, null and empty input', () => {
        expect(formatDateTime()).toBe(EMPTY_VALUE);
        expect(formatDateTime(null)).toBe(EMPTY_VALUE);
        expect(formatDateTime('')).toBe(EMPTY_VALUE);
    });
});

describe('formatDate', () => {
    it('formats an ISO datetime into a localized date', () => {
        const formatted = formatDate('2026-08-05T10:30:00.000Z');

        expect(formatted).not.toBe(EMPTY_VALUE);
        expect(formatted).toContain('2026');
    });

    it('drops the time part that formatDateTime keeps', () => {
        // The whole reason both exist: table columns want the date alone. `10:30` must not survive.
        expect(formatDate('2026-08-05T10:30:00.000Z')).not.toContain('30');
    });

    it('falls back for undefined, null and empty input', () => {
        expect(formatDate()).toBe(EMPTY_VALUE);
        expect(formatDate(null)).toBe(EMPTY_VALUE);
        expect(formatDate('')).toBe(EMPTY_VALUE);
    });
});

describe('formatCurrency', () => {
    it('formats a number with two decimals and a currency symbol', () => {
        const formatted = formatCurrency(1234.5);

        expect(formatted).toMatch(/1.234[,.]50/);
        expect(formatted).toMatch(/€|EUR/);
    });

    it('honours an explicit currency code', () => {
        expect(formatCurrency(10, 'USD')).toMatch(/\$|USD/);
    });

    it('honours explicit Intl options', () => {
        expect(formatCurrency(10, 'EUR', { minimumFractionDigits: 0 })).not.toContain('.00');
    });

    it('degrades to a plain number format for an invalid currency code', () => {
        const formatted = formatCurrency(10, 'NOT-A-CURRENCY');

        expect(formatted).not.toBe(EMPTY_VALUE);
        expect(formatted).toContain('10');
    });

    it('falls back for anything that is not a number', () => {
        expect(formatCurrency()).toBe(EMPTY_VALUE);
        expect(formatCurrency(null)).toBe(EMPTY_VALUE);
    });

    it('formats zero rather than treating it as missing', () => {
        expect(formatCurrency(0)).not.toBe(EMPTY_VALUE);
    });
});

describe('formatTime', () => {
    it('renders a time of day rather than a whole timestamp', () => {
        const formatted = formatTime('2026-02-03T14:05:09.000Z');

        // The date must not appear — this is the column where a timestamp is noise.
        expect(formatted).not.toContain('2026');
        expect(formatted).toMatch(/\d{1,2}[.:]\d{2}/);
    });

    it('falls back for undefined and null', () => {
        expect(formatTime()).toBe(EMPTY_VALUE);
        expect(formatTime(null)).toBe(EMPTY_VALUE);
    });
});

describe('formatMegabytes', () => {
    it('rounds bytes to whole megabytes and names the unit', () => {
        expect(formatMegabytes(44 * 1024 * 1024)).toBe('44 MB');
    });

    it('rounds rather than truncating', () => {
        // 1.7 MB is nearer 2 than 1; truncation would report a leak as flat.
        expect(formatMegabytes(Math.round(1.7 * 1024 * 1024))).toBe('2 MB');
    });

    it('renders zero rather than treating it as missing', () => {
        expect(formatMegabytes(0)).toBe('0 MB');
    });

    it('falls back for undefined and null', () => {
        expect(formatMegabytes()).toBe(EMPTY_VALUE);
        expect(formatMegabytes(null)).toBe(EMPTY_VALUE);
    });
});

describe('formatFlag', () => {
    it('picks the true label', () => {
        expect(formatFlag(true, 'Active', 'Inactive')).toBe('Active');
    });

    it('picks the false label', () => {
        expect(formatFlag(false, 'Active', 'Inactive')).toBe('Inactive');
    });

    it('falls back for undefined and null, which are not "false"', () => {
        expect(formatFlag(undefined, 'Active', 'Inactive')).toBe(EMPTY_VALUE);
        expect(formatFlag(null, 'Active', 'Inactive')).toBe(EMPTY_VALUE);
    });
});

describe('formatUptime', () => {
    it('falls back for undefined', () => {
        expect(formatUptime()).toBe(EMPTY_VALUE);
    });

    it('renders minutes alone under an hour', () => {
        expect(formatUptime(300)).toBe('5m');
    });

    it('renders zero minutes rather than treating it as missing', () => {
        expect(formatUptime(0)).toBe('0m');
    });

    it('renders hours and minutes once past an hour', () => {
        expect(formatUptime(7500)).toBe('2h 5m');
    });
});

/**
 * The two bindings this module exists for, asserted at their fallback edge.
 *
 * Both are `||`/`??` expressions whose right-hand side only runs in a configuration the suite
 * never otherwise reaches — an unset env var, an i18n runtime with no active locale. They are one
 * character each and invisible in review, and getting either backwards is not a crash: it is every
 * date on every page silently rendered in the wrong locale, or the fallback glyph printed as the
 * literal string `undefined`.
 */
describe('the app-shaped bindings', () => {
    beforeEach(() => {
        vi.resetModules();
        vi.unstubAllEnvs();
    });

    afterEach(() => {
        vi.unstubAllEnvs();
        vi.doUnmock('@/infrastructure/i18n');
    });

    it('falls back to an em dash when VITE_APP_EMPTY_VALUE is unset', async () => {
        vi.stubEnv('VITE_APP_EMPTY_VALUE', undefined);

        const { EMPTY_VALUE: fallback } = await import('@/infrastructure/utils/formatters');

        expect(fallback).toBe('—');
    });

    it('takes the configured glyph when the deployment sets one', async () => {
        vi.stubEnv('VITE_APP_EMPTY_VALUE', 'N/A');

        const { EMPTY_VALUE: configured } = await import('@/infrastructure/utils/formatters');

        expect(configured).toBe('N/A');
    });

    it('passes undefined rather than an empty string when no locale is active', async () => {
        // `Intl` treats `undefined` as "use the runtime default" and `''` as a RangeError, so the
        // `|| undefined` is what keeps a locale-less boot from throwing on the first date.
        vi.doMock('@/infrastructure/i18n', () => ({ getCurrentLocale: () => '' }));

        const { formatDateTime: withoutLocale } = await import('@/infrastructure/utils/formatters');

        expect(() => withoutLocale('2026-08-12T10:00:00.000Z')).not.toThrow();
        expect(withoutLocale('2026-08-12T10:00:00.000Z')).not.toBe(EMPTY_VALUE);
    });
});

tests/unit/infrastructure/utils/errors.s.source:
import { beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import {
    notifyErrorMessages,
    VUETIFY_INVALID_FIELD_SELECTOR
} from '@/infrastructure/utils/errors.ts';
import { loadLocale } from '@/infrastructure/i18n';
import enMessages from '@/locales/en.json';

/**
 * The "nothing usable in the error" fallback is translated copy now, so the dictionary has to be
 * loaded or every such assertion would compare against a raw key.
 */
beforeAll(() => loadLocale('en'));

/**
 * The observability store is stubbed so the "reported to Faro" half of `notifyErrorMessages`
 * is observable: the real `captureException` is a deliberate no-op until Faro connects, so
 * against the real store every assertion about reporting would pass vacuously.
 */
const captureExceptionMock = vi.fn();
vi.mock('@/infrastructure/stores/observability.ts', () => ({
    useObservabilityStore: () => ({ captureException: captureExceptionMock })
}));

describe('notifyErrorMessages', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    it('shows the error message when it is a string', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, 'email already registered');
        expect(addMessage).toHaveBeenCalledWith('email already registered');
    });

    it('shows the message of an Error instance', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, new Error('network down'));
        expect(addMessage).toHaveBeenCalledWith('network down');
    });

    it('shows the message property of an error-like object', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: 'Forbidden' });
        expect(addMessage).toHaveBeenCalledWith('Forbidden');
    });

    it('falls back to a generic message for unrecognized errors', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, 42);
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    // The `&& error` / `&& error.message` guards below each exist to stop an *empty* message
    // being shown to a user as if it were an explanation. They are individually invisible in a
    // review and individually easy to drop, so each falsy shape gets its own case.

    it('falls back rather than showing an empty string', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, '');
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back rather than showing an Error with an empty message', () => {
        const addMessage = vi.fn();
        // eslint-disable-next-line unicorn/error-message -- the empty message is the input under test
        notifyErrorMessages(addMessage, new Error(''));
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back rather than showing an error-like object with an empty message', () => {
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: '' });
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back when the message property is not a string', () => {
        // e.g. a parsed API body whose `message` is an array of validation errors — rendering
        // that raw would put "[object Object]" in front of a user.
        const addMessage = vi.fn();
        notifyErrorMessages(addMessage, { message: { nested: true } });
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('falls back for null without throwing', () => {
        // `typeof null === 'object'`, so the `error &&` guard is the only thing preventing a
        // TypeError here — and `null` is what an empty rejected body deserialises to.
        const addMessage = vi.fn();
        expect(() => notifyErrorMessages(addMessage, null)).not.toThrow();
        expect(addMessage).toHaveBeenCalledWith(enMessages['api-errors'].unknown);
    });

    it('reports the original value to observability, not the derived message', () => {
        // The user gets a readable string; telemetry must get the real thing, stack included,
        // or the report is worthless for debugging.
        const error = new Error('network down');

        notifyErrorMessages(vi.fn(), error);

        expect(captureExceptionMock).toHaveBeenCalledWith(error);
    });

    it('reports even when the message could not be derived', () => {
        // The fallback path is the one where telemetry matters most: nobody can act on
        // "Unknown error" without the underlying value.
        notifyErrorMessages(vi.fn(), 42);

        expect(captureExceptionMock).toHaveBeenCalledWith(42);
    });
});

/**
 * Renders Vuetify-shaped markup and returns what the selector picks out of it.
 */
const firstMatch = (html: string) => {
    const form = document.createElement('form');
    form.innerHTML = html;
    document.body.append(form);
    const found = form.querySelector<HTMLElement>(VUETIFY_INVALID_FIELD_SELECTOR);
    form.remove();
    return found;
};

describe('VUETIFY_INVALID_FIELD_SELECTOR', () => {
    /**
     * The focusing itself is `useStructureFormValidation`'s, and tested there. What belongs to
     * this repo is the selector: the toolkit's `[aria-invalid="true"]` default does not fit
     * Vuetify, where only the wrapper carries the error state. So these assert what the selector
     * finds in Vuetify-shaped markup, which is what breaks if Vuetify renames a class.
     */
    it('finds the input inside a field in error', () => {
        expect(firstMatch('<div class="v-input--error"><input id="target" /></div>')?.id).toBe(
            'target'
        );
    });

    it('finds the FIRST invalid field when several are in error', () => {
        // "first invalid field" is the accessibility contract; focusing the last would move the
        // user past the error they need to fix.
        expect(
            firstMatch(
                '<div class="v-input--error"><input id="first" /></div>' +
                    '<div class="v-input--error"><input id="second" /></div>'
            )?.id
        ).toBe('first');
    });

    it('ignores fields that are not in an error state', () => {
        expect(
            firstMatch(
                '<div><input id="valid" /></div>' +
                    '<div class="v-input--error"><input id="invalid" /></div>'
            )?.id
        ).toBe('invalid');
    });

    it('falls back to [tabindex] for controls with no native input', () => {
        // v-select and friends expose no focusable input/textarea/select of their own; without
        // the trailing selector they would be silently unreachable.
        expect(
            firstMatch('<div class="v-input--error"><div id="select" tabindex="0"></div></div>')?.id
        ).toBe('select');
    });

    it('covers textarea and select too', () => {
        expect(
            firstMatch('<div class="v-input--error"><textarea id="area"></textarea></div>')?.id
        ).toBe('area');
        expect(
            firstMatch('<div class="v-input--error"><select id="pick"></select></div>')?.id
        ).toBe('pick');
    });

    it('matches nothing when no field is in error', () => {
        expect(firstMatch('<div><input id="valid" /></div>')).toBeNull();
    });
});

