/**
 * The two dictionary conversions — the only real logic this module owns, and pure, so this is
 * where the edge cases live: arrays folding to numeric keys and back, deep nesting, the
 * deeper-key-wins rule on data the API should never produce but a test can.
 */
import { describe, expect, it } from 'vitest';
import { flattenDictionary, expandEntries } from '@/modules/locales/dictionaries.ts';

describe('flattenDictionary', () => {
    it('flattens nested objects into dotted rows', () => {
        expect(
            flattenDictionary({ products: { list: { title: 'Catalogue', empty: 'Nothing' } } })
        ).toEqual([
            { key: 'products.list.title', value: 'Catalogue' },
            { key: 'products.list.empty', value: 'Nothing' }
        ]);
    });

    it('flattens arrays to numeric segments, because the static pages keep lists in them', () => {
        expect(flattenDictionary({ faq: ['first', 'second'] })).toEqual([
            { key: 'faq.0', value: 'first' },
            { key: 'faq.1', value: 'second' }
        ]);
    });

    it('answers nothing for an empty dictionary', () => {
        expect(flattenDictionary({})).toEqual([]);
    });
});

describe('expandEntries', () => {
    it('rebuilds the nested tree from dotted rows', () => {
        expect(
            expandEntries([
                { key: 'products.list.title', value: 'Catalogue' },
                { key: 'generic.search', value: 'Search' }
            ])
        ).toEqual({
            products: { list: { title: 'Catalogue' } },
            generic: { search: 'Search' }
        });
    });

    it('folds all-numeric nodes back into arrays, so array messages round-trip', () => {
        expect(
            expandEntries([
                { key: 'faq.0', value: 'first' },
                { key: 'faq.1', value: 'second' }
            ])
        ).toEqual({ faq: ['first', 'second'] });
    });

    it('sorts numeric segments numerically, not lexically', () => {
        expect(
            expandEntries([
                { key: 'list.10', value: 'tenth' },
                { key: 'list.2', value: 'second' }
            ])
        ).toEqual({ list: ['second', 'tenth'] });
    });

    it('keeps a mixed-key node an object', () => {
        expect(
            expandEntries([
                { key: 'node.0', value: 'zero' },
                { key: 'node.name', value: 'named' }
            ])
        ).toEqual({ node: { 0: 'zero', name: 'named' } });
    });

    it('lets the deeper key win a collision the API should have refused', () => {
        expect(
            expandEntries([
                { key: 'products.list', value: 'shallow' },
                { key: 'products.list.title', value: 'deep' }
            ])
        ).toEqual({ products: { list: { title: 'deep' } } });
        // Same outcome in the other insertion order — which one survives must not depend on it.
        expect(
            expandEntries([
                { key: 'products.list.title', value: 'deep' },
                { key: 'products.list', value: 'shallow' }
            ])
        ).toEqual({ products: { list: { title: 'deep' } } });
    });

    it('round-trips a realistic dictionary through both conversions', () => {
        const dictionary = {
            navigation: { 'label-home': 'home', 'label-menu': 'Menu' },
            'static-pages': { faq: ['one', 'two', 'three'] },
            generic: { product: 'product | products' }
        };
        expect(expandEntries(flattenDictionary(dictionary))).toEqual(dictionary);
    });
});

src/modules/orders/tests/cancel.spec.ts.source:
/**
 * `cancelOrder` — the orders store's one customer write. Transport-mocked like the other store
 * flow specs; what is pinned is that the cancelled record REPLACES the cached one (the fact
 * worth rendering is the new status. A payload-less 200 cannot reach this store: `orvalMutator`
 * validates every response against its contract schema in every mode but vitest — see
 * http-validate-responses.spec.ts, which owns that behaviour.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useOrdersStore } from '@/modules/orders/store.ts';

const ORDER = {
    id: 'o1',
    userId: 'u1',
    email: 'ada@example.com',
    items: [],
    totalItems: 0,
    totalQuantity: 0,
    totalPrice: 0,
    status: 'cancelled'
};

let responses: Record<string, unknown>;

/** Every request the store made, so the BODY can be asserted and not just the URL. */
let sent: { url: string; method: string; data?: unknown }[];

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string; data?: unknown }) => {
        sent.push(config);
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(responses[key]);
    })
}));

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    sent = [];
    responses = {
        'POST /orders/o1/cancel': { data: ORDER }
    };
});

describe('cancelOrder', () => {
    it('replaces the cached record with the cancelled one', () => {
        const store = useOrdersStore();
        return store.cancelOrder('o1').then(() => {
            expect(store.orders.o1?.status).toBe('cancelled');
        });
    });
});

describe('cancelOrder — the operator choosing what happens to the money', () => {
    it('sends no body at all when nothing was chosen', () => {
        // A customer cancel is the API's default, and an absent body is what asks for it. Sending
        // `{ refund: true }` here would state a preference the caller never expressed.
        const store = useOrdersStore();

        return store.cancelOrder('o1').then(() => {
            expect(sent[0]?.data).toBeUndefined();
        });
    });

    it('asks for a cancel without a refund when told to', () => {
        const store = useOrdersStore();

        return store.cancelOrder('o1', false).then(() => {
            expect(sent[0]?.data).toEqual({ refund: false });
        });
    });

    it('asks for the money back when told to', () => {
        const store = useOrdersStore();

        return store.cancelOrder('o1', true).then(() => {
            expect(sent[0]?.data).toEqual({ refund: true });
        });
    });
});

