src/modules/cart/tests/quantity.spec.ts.source:
/**
 * Cart quantity rules — `src/modules/cart/domain/quantity.ts`.
 *
 * No `mount`, no Pinia, no HTTP. The rules take their inputs as arguments and hand back a verdict,
 * so these are statements about the rule rather than about a `disabled` attribute on `Cart.vue`.
 *
 * The floor is asserted through the clamp rather than through a predicate: `Cart.vue` compares
 * against `MIN_LINE_QUANTITY` inline, and `steppedQuantity` is what has to hold when a double click
 * outruns that guard.
 */

import { describe, it, expect } from 'vitest';
import { steppedQuantity, MIN_LINE_QUANTITY } from '@/modules/cart/domain';

describe('steppedQuantity', () => {
    it('steps up', () => {
        expect(steppedQuantity(2, 1)).toBe(3);
    });

    it('steps down', () => {
        expect(steppedQuantity(3, -1)).toBe(2);
    });

    // A double click can outrun the disabled guard, and `quantity: 0` violates the contract.
    it('clamps at the floor instead of reaching zero', () => {
        expect(steppedQuantity(1, -1)).toBe(MIN_LINE_QUANTITY);
    });

    it('clamps however far the step overshoots', () => {
        expect(steppedQuantity(2, -50)).toBe(MIN_LINE_QUANTITY);
    });

    /* Defensive: a line should never be below the floor, but if one is, it comes back up to it. */
    it('lifts a line that is already below the floor', () => {
        expect(steppedQuantity(0, -1)).toBe(MIN_LINE_QUANTITY);
    });
});

src/modules/admin/tests/routes.spec.ts.source:
/**
 * The access requirement every admin route declares.
 *
 * A route that quietly loses its `meta.access` is indistinguishable from a public one: it keeps
 * rendering, keeps passing every other test, and is simply open to anyone. Nothing else in the
 * suite would say so, which is why each expected value is written out rather than derived from the
 * records under test.
 *
 * Lives with the module because these are facts about THIS domain — held in one table in a
 * platform spec, deleting a domain would break that spec, see `docs/theory/modules.md`. The
 * router spec proves enforcement is *attached*; this proves the declarations are *there*.
 *
 * Asserted against the module's own route records rather than a resolved router, so it needs
 * neither the locale prefix nor the rest of the app.
 */
import { describe, expect, it } from 'vitest';
import type { RouteRecordRaw } from 'vue-router';
import routes from '../routes';

const byName = (name: string): RouteRecordRaw | undefined =>
    routes.find((route) => route.name === name);

describe('admin route access', () => {
    it.each([['Admin', 'admin']])('%s declares access: %s', (name, access) => {
        expect(byName(name)).toBeDefined();
        expect(byName(name)?.meta?.access).toBe(access);
    });

    it('declares no route this file does not know about', () => {
        // Catches a new route added without an access decision being made for it.
        expect(routes.map(({ name }) => name).toSorted()).toEqual(['Admin'].toSorted());
    });
});

